class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        seen = {}

        for i, num in enumerate(nums):
            complement = target - num
            if complement in seen:
                return [seen[complement], i]
            seen[num] = i

        return []

median-of-two-sorted-arrays.solution:
class Solution:
    def findMedianSortedArrays(self, nums1: list[int], nums2: list[int]) -> float:
        # Ensure nums1 is the shorter array to minimise search space
        if len(nums1) > len(nums2):
            nums1, nums2 = nums2, nums1

        m, n = len(nums1), len(nums2)
        total_left = (m + n + 1) // 2
        low, high = 0, m

        while low <= high:
            i = (low + high) // 2
            j = total_left - i

            left_a = nums1[i - 1] if i > 0 else float('-inf')
            right_a = nums1[i] if i < m else float('inf')
            left_b = nums2[j - 1] if j > 0 else float('-inf')
            right_b = nums2[j] if j < n else float('inf')

            if left_a <= right_b and left_b <= right_a:
                # Correct partition found
                if (m + n) % 2 == 1:
                    return float(max(left_a, left_b))
                return (max(left_a, left_b) + min(right_a, right_b)) / 2.0
            elif left_a > right_b:
                high = i - 1
            else:
                low = i + 1

        return 0.0

palindrome-number.solution:
class Solution:
    def isPalindrome(self, x: int) -> bool:
        # Negatives and numbers ending in 0 (except 0 itself) cannot be palindromes
        if x < 0 or (x % 10 == 0 and x != 0):
            return False

        reversed_half = 0
        # Reverse only the back half of the integer
        while x > reversed_half:
            reversed_half = reversed_half * 10 + (x % 10)
            x //= 10

        # Even length: x == reversed_half
        # Odd length: x == reversed_half // 10 (middle digit is ignored)
        return x == reversed_half or x == reversed_half // 10

