class Solution:
    def longestCommonPrefix(self, strs: list[str]) -> str:
        if not strs:
            return ""

        # Use the first string as a benchmark
        for i, ch in enumerate(strs[0]):
            for other in strs[1:]:
                # Stop if other string is shorter or has a mismatch
                if i == len(other) or other[i] != ch:
                    return strs[0][:i]

        return strs[0]

longest-palindromic-substring.solution:
class Solution:
    def longestPalindrome(self, s: str) -> str:
        if len(s) < 2:
            return s

        start = 0
        max_len = 1

        def expand(left: int, right: int) -> int:
            while left >= 0 and right < len(s) and s[left] == s[right]:
                left -= 1
                right += 1
            # Substring is s[left + 1 : right], length is right - left - 1
            return right - left - 1

        for i in range(len(s)):
            len_odd = expand(i, i)
            len_even = expand(i, i + 1)
            cur_len = max(len_odd, len_even)

            if cur_len > max_len:
                max_len = cur_len
                start = i - (cur_len - 1) // 2

        return s[start:start + max_len]

