class Solution:
    def countCommas(self, n: int) -> int:
        # Sum contributions layer-by-layer: every number >= 10^(3k) has a k-th comma
        total = 0
        base = 1000

        while base <= n:
            total += n - base + 1
            base *= 1000

        return total

