class Solution:
    def maxSubArray(self, nums: list[int]) -> int:
        # Initialise to the first element to handle all-negative arrays correctly
        current_sum = max_sum = nums[0]

        for x in nums[1:]:
            # Either extend existing subarray or start fresh with x
            current_sum = max(x, current_sum + x)
            max_sum = max(max_sum, current_sum)

        return max_sum

