class Solution:
    def plusOne(self, digits: list[int]) -> list[int]:
        n = len(digits)

        # Process from least significant to most significant
        for i in range(n - 1, -1, -1):
            if digits[i] < 9:
                digits[i] += 1
                return digits
            digits[i] = 0

        # All digits were 9, e.g., [9, 9] -> [0, 0] -> [1, 0, 0]
        return [1] + digits

