class Solution:
    def generate(self, numRows: int) -> list[list[int]]:
        # Base case seeded with row 0
        triangle = [[1]]

        for _ in range(numRows - 1):
            prev = triangle[-1]
            # Middle values are sums of adjacent pairs from previous row
            middle = [prev[j - 1] + prev[j] for j in range(1, len(prev))]
            triangle.append([1] + middle + [1])

        return triangle

