class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        n, m = len(haystack), len(needle)
        if m > n:
            return -1

        # Step 1: Compute LPS (Longest Proper Prefix which is also Suffix)
        lps = [0] * m
        prev_lps, i = 0, 1
        while i < m:
            if needle[i] == needle[prev_lps]:
                prev_lps += 1
                lps[i] = prev_lps
                i += 1
            elif prev_lps > 0:
                prev_lps = lps[prev_lps - 1]
            else:
                lps[i] = 0
                i += 1

        # Step 2: Search needle in haystack
        h_idx = n_idx = 0
        while h_idx < n:
            if haystack[h_idx] == needle[n_idx]:
                h_idx += 1
                n_idx += 1
                if n_idx == m:
                    return h_idx - m
            elif n_idx > 0:
                n_idx = lps[n_idx - 1]
            else:
                h_idx += 1

        return -1

