class Solution:
    def splitArray(self, nums: list[int], k: int) -> int:
        def can_split(max_sum: int) -> bool:
            pieces = 1
            current_sum = 0
            for x in nums:
                if current_sum + x > max_sum:
                    pieces += 1
                    current_sum = x
                    if pieces > k:
                        return False
                else:
                    current_sum += x
            return True

        left, right = max(nums), sum(nums)
        while left < right:
            mid = left + (right - left) // 2
            if can_split(mid):
                right = mid
            else:
                left = mid + 1
        return left

