class Solution:
    def minEatingSpeed(self, piles: list[int], h: int) -> int:
        left, right = 1, max(piles)

        def canFinish(k: int) -> bool:
            # (p + k - 1) // k computes ceil(p / k) safely with integers
            return sum((p + k - 1) // k for p in piles) <= h

        while left < right:
            mid = left + (right - left) // 2
            if canFinish(mid):
                right = mid
            else:
                left = mid + 1

        return left

