distinct-subsequences.solution:
class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        m, n = len(s), len(t)
        if n > m:
            return 0

        # dp[j] stores number of subsequences of current prefix of s matching t[:j]
        dp = [0] * (n + 1)
        dp[0] = 1  # Empty target string can always be formed 1 way

        for char_s in s:
            # Traverse backwards so dp[j-1] represents state from previous char in s
            for j in range(n, 0, -1):
                if char_s == t[j - 1]:
                    dp[j] += dp[j - 1]

        return dp[n]

3sum.solution:
class Solution:
    def threeSum(self, nums: list[int]) -> list[list[int]]:
        nums.sort()
        res = []
        n = len(nums)

        for i in range(n - 2):
            # If smallest element is > 0, no triplet can sum to 0
            if nums[i] > 0:
                break
            # Skip duplicate first elements
            if i > 0 and nums[i] == nums[i - 1]:
                continue

            left, right = i + 1, n - 1
            while left < right:
                total = nums[i] + nums[left] + nums[right]
                if total < 0:
                    left += 1
                elif total > 0:
                    right -= 1
                else:
                    res.append([nums[i], nums[left], nums[right]])
                    # Skip duplicates for left and right pointers
                    while left < right and nums[left] == nums[left + 1]:
                        left += 1
                    while left < right and nums[right] == nums[right - 1]:
                        right -= 1
                    left += 1
                    right -= 1

        return res

roman-to-integer.solution:
class Solution:
    def romanToInt(self, s: str) -> int:
        # Map Roman symbols to their base values
        roman_map = {
            'I': 1,
            'V': 5,
            'X': 10,
            'L': 50,
            'C': 100,
            'D': 500,
            'M': 1000
        }

        total = 0
        prev_val = 0

        # Process numerals right-to-left
        for char in reversed(s):
            curr_val = roman_map[char]
            if curr_val < prev_val:
                total -= curr_val
            else:
                total += curr_val
            prev_val = curr_val

        return total

