valid-anagram.solution:
class Solution:
    def isAnagram(self, s: str, t: str) -> bool:
        if len(s) != len(t):
            return False

        # Fixed-size array for 26 lowercase English characters
        counts = [0] * 26
        offset = ord('a')

        for char_s, char_t in zip(s, t):
            counts[ord(char_s) - offset] += 1
            counts[ord(char_t) - offset] -= 1

        # If strings are anagrams, every frequency offset must be 0
        return all(c == 0 for c in counts)

