        left, right = 0, len(height) - 1
        max_water = 0

        while left < right:
            width = right - left
            if height[left] < height[right]:
                max_water = max(max_water, height[left] * width)
                left += 1
            else:
                max_water = max(max_water, height[right] * width)
                right -= 1

        return max_water

valid-parentheses.solution:
class Solution:
    def isValid(self, s: str) -> bool:
        # Odd length strings can never be balanced
        if len(s) % 2 != 0:
            return False

        matching = {')': '(', ']': '[', '}': '{'}
        stack = []

        for char in s:
            if char in matching:
                # If stack is empty or top doesn't match, it's invalid
                if not stack or stack[-1] != matching[char]:
                    return False
                stack.pop()
            else:
                stack.append(char)

        # Valid only if no unclosed opening brackets remain
        return not stack

number-of-islands.solution:
class Solution:
    def numIslands(self, grid: list[list[str]]) -> int:
        if not grid or not grid[0]:
            return 0

        m, n = len(grid), len(grid[0])
        island_count = 0

        def dfs(r: int, c: int) -> None:
            # Boundary and water check
            if r < 0 or r >= m or c < 0 or c >= n or grid[r][c] != '1':
                return

            # Sink the land cell in-place to mark as visited
            grid[r][c] = '0'

            # Explore all 4 cardinal directions
            dfs(r + 1, c)
            dfs(r - 1, c)
            dfs(r, c + 1)
            dfs(r, c - 1)

        for r in range(m):
            for c in range(n):
                if grid[r][c] == '1':
                    island_count += 1
                    dfs(r, c)

        return island_count

