class Solution:
    def nextGreaterElement(self, nums1: list[int], nums2: list[int]) -> list[int]:
        nxt_greater = {}
        stack = []  # Monotonic decreasing stack

        for num in nums2:
            while stack and num > stack[-1]:
                smaller = stack.pop()
                nxt_greater[smaller] = num
            stack.append(num)

        # Unresolved elements in stack naturally default to -1
        return [nxt_greater.get(x, -1) for x in nums1]

burst-balloons.solution:
class Solution:
    def maxCoins(self, nums: list[int]) -> int:
        # Pad with 1 on both ends so we don't need boundary checks
        arr = [1] + nums + [1]
        n = len(arr)
        # dp[i][j] = max coins from strictly between i and j
        dp = [[0] * n for _ in range(n)]

        # length is the distance between i and j (j - i)
        for length in range(2, n):
            for i in range(0, n - length):
                j = i + length
                # k is the balloon burst LAST in the range (i, j)
                for k in range(i + 1, j):
                    coins = dp[i][k] + dp[k][j] + arr[i] * arr[k] * arr[j]
                    if coins > dp[i][j]:
                        dp[i][j] = coins

        return dp[0][n - 1]

