spiral-matrix.solution:
class Solution:
    def spiralOrder(self, matrix: list[list[int]]) -> list[int]:
        if not matrix or not matrix[0]:
            return []

        res = []
        top, bottom = 0, len(matrix) - 1
        left, right = 0, len(matrix[0]) - 1

        while top <= bottom and left <= right:
            # Traverse Right across top row
            for c in range(left, right + 1):
                res.append(matrix[top][c])
            top += 1

            # Traverse Down along right column
            for r in range(top, bottom + 1):
                res.append(matrix[r][right])
            right -= 1

            # Traverse Left across bottom row (guard against single remaining row)
            if top <= bottom:
                for c in range(right, left - 1, -1):
                    res.append(matrix[bottom][c])
                bottom -= 1

            # Traverse Up along left column (guard against single remaining col)
            if left <= right:
                for r in range(bottom, top - 1, -1):
                    res.append(matrix[r][left])
                left += 1

        return res

top-k-frequent-elements.solution:
class Solution:
    def topKFrequent(self, nums: list[int], k: int) -> list[int]:
        counts = collections.Counter(nums)

        # Buckets where index represents frequency (0 to len(nums))
        buckets = [[] for _ in range(len(nums) + 1)]
        for num, freq in counts.items():
            buckets[freq].append(num)

        res = []
        # Walk backwards from highest frequency
        for freq in range(len(buckets) - 1, 0, -1):
            for num in buckets[freq]:
                res.append(num)
                if len(res) == k:
                    return res
        return res

