    def hasCycle(self, head: Optional[ListNode]) -> bool:
        slow = head
        fast = head

        # Fast moves two steps, so check both fast and fast.next
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next

            if slow is fast:
                return True

        return False

