class Solution:
    def totalFruit(self, fruits: list[int]) -> int:
        # Frequency map for fruit types in our current window
        fruit_count = {}
        left = 0
        max_fruits = 0

        for right, fruit in enumerate(fruits):
            fruit_count[fruit] = fruit_count.get(fruit, 0) + 1

            # Shrink window from the left until we have at most 2 distinct fruits
            while len(fruit_count) > 2:
                left_fruit = fruits[left]
                fruit_count[left_fruit] -= 1
                if fruit_count[left_fruit] == 0:
                    del fruit_count[left_fruit]
                left += 1

            max_fruits = max(max_fruits, right - left + 1)

        return max_fruits

ransom-note.solution:
class Solution:
    def canConstruct(self, ransomNote: str, magazine: str) -> bool:
        # Quick sanity check: impossible if note is longer than magazine
        if len(ransomNote) > len(magazine):
            return False

        # Fixed-size bucket array for 'a'-'z'
        counts = [0] * 26
        offset = ord('a')

        for ch in magazine:
            counts[ord(ch) - offset] += 1

        for ch in ransomNote:
            idx = ord(ch) - offset
            counts[idx] -= 1
            if counts[idx] < 0:
                return False

        return True

cinema-seat-allocation.solution:
class Solution:
    def maxNumberOfFamilies(self, n: int, reservedSeats: list[list[int]]) -> int:
        # Map row -> bitmask of occupied seats (focusing on seats 2..9)
        occupied = {}
        for r, c in reservedSeats:
            if 2 <= c <= 9:
                occupied[r] = occupied.get(r, 0) | (1 << (c - 1))

        # Bitmasks for our 4-seat blocks (0-indexed seats: seat k is 1 << (k-1))
        left_mask = (1 << 1) | (1 << 2) | (1 << 3) | (1 << 4)     # seats 2,3,4,5
        right_mask = (1 << 5) | (1 << 6) | (1 << 7) | (1 << 8)    # seats 6,7,8,9
        mid_mask = (1 << 3) | (1 << 4) | (1 << 5) | (1 << 6)      # seats 4,5,6,7

        # Rows with no reservations in 2..9 can hold 2 families
        ans = 2 * (n - len(occupied))

        for mask in occupied.values():
            left_ok = (mask & left_mask) == 0
            right_ok = (mask & right_mask) == 0
            mid_ok = (mask & mid_mask) == 0

            if left_ok and right_ok:
                ans += 2
            elif left_ok or right_ok or mid_ok:
                ans += 1

        return ans

single-number-ii.solution:
class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        ones = 0
        twos = 0

        for num in nums:
            # Add num to 'ones' only if it's not already in 'twos'
            ones = (ones ^ num) & ~twos
            # Add num to 'twos' only if it's not in the updated 'ones'
            twos = (twos ^ num) & ~ones

        return ones

