class Solution:
    def myPow(self, x: float, n: int) -> float:
        # Handle negative exponent upfront
        if n < 0:
            x = 1.0 / x
            n = -n

        ans = 1.0
        curr = x

        # Binary exponentiation
        while n > 0:
            if n % 2 == 1:
                ans *= curr
            curr *= curr
            n //= 2

        return ans

longest-valid-parentheses.solution:
class Solution:
    def longestValidParentheses(self, s: str) -> int:
        # stack stores indices; -1 serves as the initial boundary base
        stack = [-1]
        max_len = 0

        for i, ch in enumerate(s):
            if ch == '(':
                stack.append(i)
            else:
                stack.pop()
                if not stack:
                    # Unmatched ')' becomes the new base boundary
                    stack.append(i)
                else:
                    # Current valid sequence spans from stack[-1] + 1 to i
                    max_len = max(max_len, i - stack[-1])

        return max_len

