class StockSpanner:

    def __init__(self):
        # Stack stores (price, span) maintaining strictly decreasing prices
        self.stack = []

    def next(self, price: int) -> int:
        span = 1
        # Collapse all prior days dominated by the current price
        while self.stack and self.stack[-1][0] <= price:
            span += self.stack.pop()[1]

        self.stack.append((price, span))
        return span

