class Solution:
    def isSubsequence(self, s: str, t: str) -> bool:
        # Edge case: empty s is always a subsequence
        if not s:
            return True

        i, j = 0, 0
        len_s, len_t = len(s), len(t)

        while i < len_s and j < len_t:
            if s[i] == t[j]:
                i += 1
            j += 1

        return i == len_s

