class Solution:
    def rob(self, nums: list[int]) -> int:
        if len(nums) == 1:
            return nums[0]

        def rob_linear(start: int, end: int) -> int:
            prev2, prev1 = 0, 0
            for i in range(start, end + 1):
                curr = max(prev1, prev2 + nums[i])
                prev2 = prev1
                prev1 = curr
            return prev1

        n = len(nums)
        # Case 1: Rob within [0, n-2] (excludes last house)
        # Case 2: Rob within [1, n-1] (excludes first house)
        return max(rob_linear(0, n - 2), rob_linear(1, n - 1))

path-sum-ii.solution:
class Solution:
    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> List[List[int]]:
        result = []
        path = []

        def dfs(node: Optional[TreeNode], remaining: int) -> None:
            if not node:
                return

            path.append(node.val)

            # If it's a leaf node and value matches remaining target
            if not node.left and not node.right and node.val == remaining:
                result.append(list(path))
            else:
                # Only recurse to existing children to avoid redundant calls
                if node.left:
                    dfs(node.left, remaining - node.val)
                if node.right:
                    dfs(node.right, remaining - node.val)

            # Backtrack
            path.pop()

        dfs(root, targetSum)
        return result

search-in-rotated-sorted-array.solution:
class Solution:
    def search(self, nums: list[int], target: int) -> int:
        left, right = 0, len(nums) - 1

        while left <= right:
            mid = left + (right - left) // 2

            if nums[mid] == target:
                return mid

            # Check if the left half is sorted
            if nums[left] <= nums[mid]:
                # Does target fall in the sorted left half?
                if nums[left] <= target < nums[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
            # Otherwise, the right half must be sorted
            else:
                # Does target fall in the sorted right half?
                if nums[mid] < target <= nums[right]:
                    left = mid + 1
                else:
                    right = mid - 1

        return -1

coin-change.solution:
class Solution:
    def coinChange(self, coins: list[int], amount: int) -> int:
        # dp[i] represents fewest coins to make amount i
        # amount + 1 acts as infinity
        dp = [amount + 1] * (amount + 1)
        dp[0] = 0

        coins.sort()
        for i in range(1, amount + 1):
            for c in coins:
                if c > i:
                    break  # Coins are sorted, no need to check larger ones
                dp[i] = min(dp[i], 1 + dp[i - c])

        return dp[amount] if dp[amount] <= amount else -1

jump-game-ii.solution:
class Solution:
    def jump(self, nums: list[int]) -> int:
        n = len(nums)
        if n <= 1:
            return 0

        jumps = 0
        current_end = 0
        farthest = 0

        # Stop at n - 2 so we don't trigger an extra jump at the last index
        for i in range(n - 1):
            farthest = max(farthest, i + nums[i])

            if i == current_end:
                jumps += 1
                current_end = farthest

                # Optional early exit if we can already reach the end
                if current_end >= n - 1:
                    break

        return jumps

happy-number.solution:
class Solution:
    def isHappy(self, n: int) -> bool:
        def get_next(number: int) -> int:
            total = 0
            while number > 0:
                number, digit = divmod(number, 10)
                total += digit * digit
            return total

        slow = n
        fast = get_next(n)

        # Floyd's cycle detection: fast moves two steps for slow's one
        while fast != 1 and slow != fast:
            slow = get_next(slow)
            fast = get_next(get_next(fast))

        return fast == 1

sort-an-array.solution:
class Solution:
    def sortArray(self, nums: list[int]) -> list[int]:
        n = len(nums)

        def sift_down(heap_size: int, root: int) -> None:
            curr = root
            while True:
                largest = curr
                left = 2 * curr + 1
                right = 2 * curr + 2

                if left < heap_size and nums[left] > nums[largest]:
                    largest = left
                if right < heap_size and nums[right] > nums[largest]:
                    largest = right

                if largest != curr:
                    nums[curr], nums[largest] = nums[largest], nums[curr]
                    curr = largest
                else:
                    break

        # Build max-heap bottom-up: O(n)
        for i in range(n // 2 - 1, -1, -1):
            sift_down(n, i)

        # Extract max elements: O(n log n)
        for i in range(n - 1, 0, -1):
            nums[0], nums[i] = nums[i], nums[0]
            sift_down(i, 0)

        return nums

integer-to-roman.solution:
class Solution:
    def intToRoman(self, num: int) -> str:
        # All 13 distinct standard and subtractive Roman numeral values
        val_to_sym = [
            (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
            (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
            (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
        ]

        res = []
        for val, sym in val_to_sym:
            if num == 0:
                break
            count, num = divmod(num, val)
            if count:
                res.append(sym * count)

        return "".join(res)

