longest-non-decreasing-subarray-after-re.solution:
class Solution:
    def maxNonDecreasingLength(self, nums: list[int]) -> int:
        n = len(nums)
        if n <= 2:
            return n

        # pref[i]: length of longest non-decreasing subarray ending at i
        pref = [1] * n
        for i in range(1, n):
            if nums[i] >= nums[i - 1]:
                pref[i] = pref[i - 1] + 1

        # suff[i]: length of longest non-decreasing subarray starting at i
        suff = [1] * n
        for i in range(n - 2, -1, -1):
            if nums[i] <= nums[i + 1]:
                suff[i] = suff[i + 1] + 1

        # Baseline: extend any existing valid contiguous run by 1
        ans = min(n, max(pref) + 1)

        # Try replacing nums[i] to bridge pref[i-1] and suff[i+1]
        for i in range(1, n - 1):
            ans = max(ans, pref[i - 1] + 1, suff[i + 1] + 1)
            if nums[i - 1] <= nums[i + 1]:
                ans = max(ans, pref[i - 1] + 1 + suff[i + 1])

        return min(n, ans)

making-a-large-island.solution:
class Solution:
    def largestIsland(self, grid: list[list[int]]) -> int:
        n = len(grid)
        island_id = 2
        areas = {0: 0}

        def dfs(r: int, c: int, tag: int) -> int:
            grid[r][c] = tag
            size = 1
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == 1:
                    size += dfs(nr, nc, tag)
            return size

        max_size = 0
        # Step 1: Label each island with a unique ID and store its size
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 1:
                    areas[island_id] = dfs(r, c, island_id)
                    max_size = max(max_size, areas[island_id])
                    island_id += 1

        # Step 2: Try turning each 0 into 1 and bridge surrounding islands
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    seen_ids = set()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] > 1:
                            seen_ids.add(grid[nr][nc])

                    cand_size = 1 + sum(areas[tag] for tag in seen_ids)
                    max_size = max(max_size, cand_size)

        return max_size

