valid-palindrome-ii.solution:
class Solution:
    def validPalindrome(self, s: str) -> bool:
        def is_pali(l: int, r: int) -> bool:
            while l < r:
                if s[l] != s[r]:
                    return False
                l += 1
                r -= 1
            return True

        l, r = 0, len(s) - 1
        while l < r:
            if s[l] != s[r]:
                # Try skipping left character OR right character
                return is_pali(l + 1, r) or is_pali(l, r - 1)
            l += 1
            r -= 1

        return True

maximal-square.solution:
class Solution:
    def maximalSquare(self, matrix: List[List[str]]) -> int:
        if not matrix or not matrix[0]:
            return 0

        m, n = len(matrix), len(matrix[0])
        dp = [0] * (n + 1)
        max_side = 0

        for r in range(m):
            prev = 0  # Represents dp[r-1][c-1] (top-left diagonal)
            for c in range(n):
                temp = dp[c + 1]  # Save before overwriting, will be next prev
                if matrix[r][c] == '1':
                    # dp[c] is left, dp[c+1] is top, prev is top-left
                    dp[c + 1] = 1 + min(dp[c], dp[c + 1], prev)
                    max_side = max(max_side, dp[c + 1])
                else:
                    dp[c + 1] = 0
                prev = temp

        return max_side * max_side

