class Solution:
    def findPeakElement(self, nums: list[int]) -> int:
        left, right = 0, len(nums) - 1

        # Converge towards a single peak index
        while left < right:
            mid = left + (right - left) // 2

            # If ascending, peak must be on the right
            if nums[mid] < nums[mid + 1]:
                left = mid + 1
            else:
                # If descending, mid could be the peak or peak is to the left
                right = mid

        return left

combination-sum.solution:
class Solution:
    def combinationSum(self, candidates: list[int], target: int) -> list[list[int]]:
        candidates.sort()
        results = []

        def backtrack(start_idx: int, remain: int, path: list[int]) -> None:
            if remain == 0:
                results.append(list(path))
                return

            for i in range(start_idx, len(candidates)):
                val = candidates[i]
                # Since candidates is sorted, no subsequent element will fit
                if val > remain:
                    break

                path.append(val)
                # Pass i (not i + 1) because we can reuse the current element
                backtrack(i, remain - val, path)
                path.pop()

        backtrack(0, target, [])
        return results

redundant-connection.solution:
class Solution:
    def findRedundantConnection(self, edges: list[list[int]]) -> list[int]:
        n = len(edges)
        parent = list(range(n + 1))
        rank = [0] * (n + 1)

        def find(x: int) -> int:
            # Path compression
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x: int, y: int) -> bool:
            root_x, root_y = find(x), find(y)
            if root_x == root_y:
                return False  # Cycle detected

            # Union by rank
            if rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            elif rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            else:
                parent[root_y] = root_x
                rank[root_x] += 1
            return True

        for u, v in edges:
            if not union(u, v):
                return [u, v]

        return []

