class Solution:
    def findMin(self, nums: list[int]) -> int:
        left, right = 0, len(nums) - 1

        # Converge until search space is one element
        while left < right:
            mid = left + (right - left) // 2

            if nums[mid] > nums[right]:
                # Minimum is strictly to the right of mid
                left = mid + 1
            else:
                # Minimum is mid or to the left of mid
                right = mid

        return nums[left]

