import math

class Solution:
    def gcdOfStrings(self, str1: str, str2: str) -> str:
        # If concatenation in both orders differs, no common divisor exists
        if str1 + str2 != str2 + str1:
            return ""

        # GCD of lengths gives the exact length of the largest divisor string
        gcd_len = math.gcd(len(str1), len(str2))
        return str1[:gcd_len]

string-compression.solution:
class Solution:
    def compress(self, chars: list[str]) -> int:
        write = 0
        read = 0
        n = len(chars)

        while read < n:
            start = read
            # Advance read pointer through the contiguous group
            while read < n and chars[read] == chars[start]:
                read += 1

            # Write the group's character
            chars[write] = chars[start]
            write += 1

            count = read - start
            # Write count digits only if run is strictly greater than 1
            if count > 1:
                for digit in str(count):
                    chars[write] = digit
                    write += 1

        return write

the-earliest-moment-when-everyone-become.solution:
class DSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.components = n

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])  # Path compression
        return self.parent[x]

    def union(self, x: int, y: int) -> bool:
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x == root_y:
            return False

        # Union by rank
        if self.rank[root_x] < self.rank[root_y]:
            self.parent[root_x] = root_y
        elif self.rank[root_x] > self.rank[root_y]:
            self.parent[root_y] = root_x
        else:
            self.parent[root_y] = root_x
            self.rank[root_x] += 1

        self.components -= 1
        return True


class Solution:
    def earliestAcq(self, logs: list[list[int]], n: int) -> int:
        # Sort logs chronologically by timestamp
        logs.sort(key=lambda x: x[0])

        dsu = DSU(n)

        for ts, u, v in logs:
            if dsu.union(u, v) and dsu.components == 1:
                return ts

        return -1

