class Solution:
    def subsets(self, nums: list[int]) -> list[list[int]]:
        res = []
        path = []

        def backtrack(start: int) -> None:
            # Record current subset snapshot
            res.append(list(path))

            for i in range(start, len(nums)):
                path.append(nums[i])
                backtrack(i + 1)
                path.pop()  # undo choice

        backtrack(0)
        return res

network-delay-time.solution:
import heapq
from collections import defaultdict

class Solution:
    def networkDelayTime(self, times: list[list[int]], n: int, k: int) -> int:
        # Build adjacency list: u -> list of (travel_time, v)
        adj = defaultdict(list)
        for u, v, w in times:
            adj[u].append((w, v))

        # Min-heap stores (total_time_so_far, node)
        pq = [(0, k)]
        dist = {}

        while pq:
            d, u = heapq.heappop(pq)

            # Skip if we have already found a shorter path to u
            if u in dist:
                continue
            dist[u] = d

            # Early exit if all nodes have been visited
            if len(dist) == n:
                return d

            for weight, v in adj[u]:
                if v not in dist:
                    heapq.heappush(pq, (d + weight, v))

        return -1

regular-expression-matching.solution:
class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        m, n = len(s), len(p)
        # dp[i][j] will be True if s[i:] matches p[j:]
        dp = [[False] * (n + 1) for _ in range(m + 1)]
        dp[m][n] = True

        # Handle empty string matching pattern suffixes with '*'
        for j in range(n - 1, -1, -1):
            if j + 1 < n and p[j + 1] == '*':
                dp[m][j] = dp[m][j + 2]

        # Fill from bottom-up
        for i in range(m - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                first_match = p[j] in {s[i], '.'}

                if j + 1 < n and p[j + 1] == '*':
                    # Zero occurrences of p[j] OR one match and stay on current pattern
                    dp[i][j] = dp[i][j + 2] or (first_match and dp[i + 1][j])
                else:
                    # Exact single char or dot match
                    dp[i][j] = first_match and dp[i + 1][j + 1]

        return dp[0][0]

