class Solution:
    def canMakeArithmeticProgression(self, arr: list[int]) -> bool:
        min_val = min(arr)
        max_val = max(arr)
        n = len(arr)

        # Difference between max and min must divide evenly across (n - 1) gaps
        if (max_val - min_val) % (n - 1) != 0:
            return False

        diff = (max_val - min_val) // (n - 1)
        if diff == 0:
            return True

        seen = set(arr)
        # If there are duplicate items with non-zero diff, it cannot form an AP
        if len(seen) != n:
            return False

        # Verify every expected term in the progression exists
        for i in range(n):
            if (min_val + i * diff) not in seen:
                return False

        return True

