from collections import deque

class Solution:
    def minMoves(self, classroom: list[str], energy: int) -> int:
        m, n = len(classroom), len(classroom[0])
        litter_map = {}
        sr, sc = 0, 0

        for r in range(m):
            for c in range(n):
                val = classroom[r][c]
                if val == 'S':
                    sr, sc = r, c
                elif val == 'L':
                    litter_map[(r, c)] = len(litter_map)

        num_litters = len(litter_map)
        if num_litters == 0:
            return 0

        target_mask = (1 << num_litters) - 1
        # best_energy[r][c][mask] stores max energy seen so far
        best_energy = [[[-1] * (1 << num_litters) for _ in range(n)] for _ in range(m)]

        q = deque([(sr, sc, 0, energy, 0)])
        best_energy[sr][sc][0] = energy

        while q:
            r, c, mask, cur_e, steps = q.popleft()

            if mask == target_mask:
                return steps

            if cur_e == 0:
                continue

            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and classroom[nr][nc] != 'X':
                    cell = classroom[nr][nc]
                    nxt_e = energy if cell == 'R' else cur_e - 1
                    nxt_mask = mask | (1 << litter_map[(nr, nc)]) if cell == 'L' else mask

                    if nxt_e > best_energy[nr][nc][nxt_mask]:
                        best_energy[nr][nc][nxt_mask] = nxt_e
                        q.append((nr, nc, nxt_mask, nxt_e, steps + 1))

        return -1

