class Solution:
    def calculateMinimumHP(self, dungeon: list[list[int]]) -> int:
        m, n = len(dungeon), len(dungeon[0])
        # dp[c] stores min HP needed entering cell (r, c)
        # Size n + 1 handles right-boundary cleanly with inf
        dp = [float('inf')] * (n + 1)
        dp[n - 1] = 1  # Base requirement to stay alive after princess room

        for r in reversed(range(m)):
            for c in reversed(range(n)):
                # Health needed to survive the next room
                min_next = min(dp[c], dp[c + 1])
                # Required health entering room (r, c)
                dp[c] = max(1, min_next - dungeon[r][c])

        return int(dp[0])

top-k-frequent-words.solution:
import heapq
from collections import Counter

class Element:
    def __init__(self, freq: int, word: str):
        self.freq = freq
        self.word = word

    def __lt__(self, other: 'Element') -> bool:
        # Lower frequency has higher eviction priority (min-heap top)
        if self.freq != other.freq:
            return self.freq < other.freq
        # For same frequency, lexicographically LARGER word is evicted first
        return self.word > other.word

class Solution:
    def topKFrequent(self, words: list[str], k: int) -> list[str]:
        counts = Counter(words)
        heap = []

        for word, freq in counts.items():
            heapq.heappush(heap, Element(freq, word))
            if len(heap) > k:
                heapq.heappop(heap)

        # Pop elements; they come out in reverse desired order
        res = []
        while heap:
            res.append(heapq.heappop(heap).word)

        return res[::-1]

