class Solution:
    def getSum(self, a: int, b: int) -> int:
        mask = 0xFFFFFFFF
        max_int = 0x7FFFFFFF

        # Iterate until there are no remaining carries
        while b != 0:
            carry = ((a & b) << 1) & mask
            a = (a ^ b) & mask
            b = carry

        # If a is negative in 32-bit two's complement, convert to Python signed int
        return a if a <= max_int else ~(a ^ mask)

