        for i in range(n - 2, -1, -1):
            suff_min[i] = min(nums[i], suff_min[i + 1])

        pref_max = 0
        for i in range(n):
            pref_max = max(pref_max, nums[i])
            if pref_max - suff_min[i] <= k:
                return i

        return -1

