class Solution:
    def minCostConnectPoints(self, points: list[list[int]]) -> int:
        n = len(points)
        if n <= 1:
            return 0

        # min_dist[i] stores the smallest distance from node i to the current MST
        min_dist = [float('inf')] * n
        min_dist[0] = 0
        visited = [False] * n
        total_cost = 0

        for _ in range(n):
            # Pick the unvisited node with the smallest edge to the tree
            u = -1
            curr_min = float('inf')
            for i in range(n):
                if not visited[i] and min_dist[i] < curr_min:
                    curr_min = min_dist[i]
                    u = i

            visited[u] = True
            total_cost += curr_min

            # Relax distances to remaining unvisited nodes
            ux, uy = points[u]
            for v in range(n):
                if not visited[v]:
                    dist = abs(ux - points[v][0]) + abs(uy - points[v][1])
                    if dist < min_dist[v]:
                        min_dist[v] = dist

        return total_cost

