class Solution:
    def maxSlidingWindow(self, nums: list[int], k: int) -> list[int]:
        q = deque()  # stores indices, monotonically decreasing by value
        res = []

        for i, num in enumerate(nums):
            # 1. Remove indices outside the current sliding window
            if q and q[0] <= i - k:
                q.popleft()

            # 2. Maintain monotonic decreasing order
            while q and nums[q[-1]] < num:
                q.pop()

            q.append(i)

            # 3. Add to result once the first full window is processed
            if i >= k - 1:
                res.append(nums[q[0]])

        return res

