class Solution:
    def addBinary(self, a: str, b: str) -> str:
        i, j = len(a) - 1, len(b) - 1
        carry = 0
        res = []

        # Process bits from right to left, including any remaining carry
        while i >= 0 or j >= 0 or carry:
            total = carry
            if i >= 0:
                total += ord(a[i]) - ord('0')
                i -= 1
            if j >= 0:
                total += ord(b[j]) - ord('0')
                j -= 1

            res.append(str(total % 2))
            carry = total // 2

        return "".join(reversed(res))

maximum-score-of-non-overlapping-interva.solution:
from bisect import bisect_left

class Solution:
    def maxWeight(self, intervals: list[list[int]]) -> list[int]:
        n = len(intervals)
        # Keep original indices: (start, end, weight, original_index)
        sorted_ints = sorted(
            (intervals[i][0], intervals[i][1], intervals[i][2], i) for i in range(n)
        )
        # Sort by end time
        sorted_ints.sort(key=lambda x: x[1])
        ends = [item[1] for item in sorted_ints]

        # Helper to decide if cand is strictly better than curr
        def is_better(cand, curr):
            if not cand[1]:
                return False
            if not curr[1]:
                return True
            if cand[0] != curr[0]:
                return cand[0] > curr[0]
            return cand[1] < curr[1]

        # dp[k][i] = (weight, [sorted_indices])
        dp = [[(0, []) for _ in range(n)] for _ in range(5)]

        for i in range(n):
            l, r, w, idx = sorted_ints[i]
            # Find latest compatible interval ending strictly before l
            j = bisect_left(ends, l) - 1

            for k in range(1, 5):
                best = dp[k][i - 1] if i > 0 else (0, [])

                if k == 1:
                    cand = (w, [idx])
                    if is_better(cand, best):
                        best = cand
                else:
                    if j >= 0 and dp[k - 1][j][0] > 0:
                        cand_w = dp[k - 1][j][0] + w
                        # Insert idx in sorted order (list has length at most 4)
                        cand_idx = sorted(dp[k - 1][j][1] + [idx])
                        cand = (cand_w, cand_idx)
                        if is_better(cand, best):
                            best = cand

                dp[k][i] = best

        # Global best across all sizes 1..4 at the final index
        ans = (0, [])
        for k in range(1, 5):
            if is_better(dp[k][n - 1], ans):
                ans = dp[k][n - 1]

        return ans[1]

