class Solution:
    def letterCombinations(self, digits: str) -> list[str]:
        if not digits:
            return []

        mapping = {
            '2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
            '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'
        }

        result = []
        path = []

        def backtrack(index: int) -> None:
            # Base case: reached full combination length
            if index == len(digits):
                result.append(''.join(path))
                return

            # Explore all candidate letters for current digit
            for char in mapping[digits[index]]:
                path.append(char)
                backtrack(index + 1)
                path.pop()  # Backtrack

        backtrack(0)
        return result

