        mask = 0

        # 31 bits suffice since 0 <= nums[i] <= 2^31 - 1
        for i in range(30, -1, -1):
            mask |= (1 << i)
            prefixes = {num & mask for num in nums}

            # Greedily hope the i-th bit can be 1
            candidate = max_xor | (1 << i)

            # If A ^ B = candidate, then A ^ candidate = B
            for prefix in prefixes:
                if candidate ^ prefix in prefixes:
                    max_xor = candidate
                    break

        return max_xor

