class Solution:
    def canPartition(self, nums: list[int]) -> bool:
        total = sum(nums)
        # If total sum is odd, cannot partition into two equal integers
        if total % 2 != 0:
            return False

        target = total // 2
        dp = [False] * (target + 1)
        dp[0] = True

        for num in nums:
            # Traverse backwards to prevent using the same element multiple times
            for j in range(target, num - 1, -1):
                dp[j] = dp[j] or dp[j - num]
            if dp[target]:
                return True

        return dp[target]

