class Solution:
    def smallestSubsequence(self, s: str) -> str:
        # Map each character to its last occurrence index
        last_idx = {c: i for i, c in enumerate(s)}

        st = []
        seen = set()

        for i, c in enumerate(s):
            # If character already included, skip to maintain best earlier choice
            if c in seen:
                continue

            # Greedily pop larger characters that appear again later
            while st and st[-1] > c and last_idx[st[-1]] > i:
                seen.remove(st.pop())

            st.append(c)
            seen.add(c)

        return "".join(st)

