class Solution:
    def decodeString(self, s: str) -> str:
        stack = []  # stores tuples of (prev_str, repeat_count)
        curr_str = ""
        curr_num = 0

        for char in s:
            if char.isdigit():
                curr_num = curr_num * 10 + int(char)
            elif char == '[':
                # Save outer context and reset current buffers
                stack.append((curr_str, curr_num))
                curr_str = ""
                curr_num = 0
            elif char == ']':
                # Resolve inner context and rejoin outer context
                prev_str, count = stack.pop()
                curr_str = prev_str + curr_str * count
            else:
                curr_str += char

        return curr_str

