class Solution:
    def myAtoi(self, s: str) -> int:
        INT_MIN, INT_MAX = -2**31, 2**31 - 1
        n = len(s)
        i = 0

        # 1. Discard leading whitespace
        while i < n and s[i] == ' ':
            i += 1

        if i == n:
            return 0

        # 2. Check sign
        sign = 1
        if s[i] == '-':
            sign = -1
            i += 1
        elif s[i] == '+':
            i += 1

        # 3. Read digits and clamp
        ans = 0
        while i < n and s[i].isdigit():
            digit = ord(s[i]) - ord('0')
            ans = ans * 10 + digit

            # Clamp early to avoid unbounded integers
            if sign == 1 and ans >= INT_MAX:
                return INT_MAX
            if sign == -1 and -ans <= INT_MIN:
                return INT_MIN

            i += 1

        return sign * ans

