class Solution:
    def predictTheWinner(self, nums: list[int]) -> bool:
        n = len(nums)
        # dp[j] holds the max score diff for subarray starting at i and ending at j
        dp = list(nums)

        for i in range(n - 2, -1, -1):
            for j in range(i + 1, n):
                # nums[i] - dp[j] uses old dp[j] (which represents dp[i+1][j])
                # nums[j] - dp[j-1] uses updated dp[j-1] (representing dp[i][j-1])
                dp[j] = max(nums[i] - dp[j], nums[j] - dp[j - 1])

        return dp[n - 1] >= 0

