class Solution:
    def maximumProduct(self, nums: list[int]) -> int:
        # Track the two smallest and three largest elements
        min1 = min2 = float("inf")
        max1 = max2 = max3 = float("-inf")

        for n in nums:
            # Cascading updates for minimums
            if n <= min1:
                min2 = min1
                min1 = n
            elif n <= min2:
                min2 = n

            # Cascading updates for maximums
            if n >= max1:
                max3 = max2
                max2 = max1
                max1 = n
            elif n >= max2:
                max3 = max2
                max2 = n
            elif n >= max3:
                max3 = n

        # Best triplet is either 3 largest or 2 smallest + 1 largest
        return max(max1 * max2 * max3, min1 * min2 * max1)

