import heapq

class Solution:
    def minMeetingRooms(self, intervals: list[list[int]]) -> int:
        if not intervals:
            return 0

        # Sort meetings by their start time
        intervals.sort(key=lambda x: x[0])

        # Min-heap tracks end times of currently used rooms
        rooms = []
        heapq.heappush(rooms, intervals[0][1])

        for start, end in intervals[1:]:
            # If earliest room freed up, reuse it
            if start >= rooms[0]:
                heapq.heappop(rooms)

            # Allocate or update room with current meeting's end time
            heapq.heappush(rooms, end)

        return len(rooms)

