class Solution:
    def validSequence(self, word1: str, word2: str) -> list[int]:
        n, m = len(word1), len(word2)
        suf = [0] * (n + 1)

        # Precompute max suffix of word2 matchable from word1[i:]
        p = m - 1
        for i in range(n - 1, -1, -1):
            if p >= 0 and word1[i] == word2[p]:
                p -= 1
            suf[i] = m - 1 - p

        ans = []
        j = 0
        changed = False

        # Greedy forward pass
        for i in range(n):
            if j == m:
                break
            if word1[i] == word2[j]:
                ans.append(i)
                j += 1
            elif not changed and suf[i + 1] >= m - 1 - j:
                ans.append(i)
                changed = True
                j += 1

        return ans if len(ans) == m else []

