    def merge(self, intervals: list[list[int]]) -> list[list[int]]:
        if not intervals:
            return []

        # Sort primarily by start time; Timsort runs in O(N log N)
        intervals.sort(key=lambda x: x[0])

        merged: list[list[int]] = []

        for start, end in intervals:
            # If merged is empty or current interval starts after previous ends
            if not merged or start > merged[-1][1]:
                merged.append([start, end])
            else:
                # Overlapping interval, absorb it by extending the end point
                merged[-1][1] = max(merged[-1][1], end)

        return merged

