import bisect
import random

class Solution:
    def __init__(self, w: list[int]):
        # Build cumulative prefix sum array
        self.prefix_sums = []
        curr = 0
        for weight in w:
            curr += weight
            self.prefix_sums.append(curr)
        self.total_sum = curr

    def pickIndex(self) -> int:
        # Target integer uniformly chosen in [1, total_sum]
        target = random.randint(1, self.total_sum)
        # First index with cumulative weight >= target
        return bisect.bisect_left(self.prefix_sums, target)

