class Solution:
    def reversePairs(self, nums: list[int]) -> int:
        def merge_sort(l: int, r: int) -> int:
            if l >= r:
                return 0

            mid = (l + r) // 2
            # Recurse on left and right halves
            total = merge_sort(l, mid) + merge_sort(mid + 1, r)

            # Step 1: Count cross-half reverse pairs
            j = mid + 1
            for i in range(l, mid + 1):
                while j <= r and nums[i] > 2 * nums[j]:
                    j += 1
                total += j - (mid + 1)

            # Step 2: Merge the two sorted halves
            merged = []
            p1, p2 = l, mid + 1
            while p1 <= mid and p2 <= r:
                if nums[p1] <= nums[p2]:
                    merged.append(nums[p1])
                    p1 += 1
                else:
                    merged.append(nums[p2])
                    p2 += 1

            while p1 <= mid:
                merged.append(nums[p1])
                p1 += 1
            while p2 <= r:
                merged.append(nums[p2])
                p2 += 1

            nums[l : r + 1] = merged
            return total

        return merge_sort(0, len(nums) - 1)

