    def smallestPalindrome(self, s: str) -> str:
        # Count character frequencies
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        left_chars = []
        mid = ""

        # Greedily build left half in alphabetical order
        for i in range(26):
            ch = chr(ord('a') + i)
            cnt = counts[i]
            if cnt % 2 == 1:
                mid = ch
            if cnt // 2 > 0:
                left_chars.append(ch * (cnt // 2))

        left_half = "".join(left_chars)
        return left_half + mid + left_half[::-1]

