from functools import lru_cache

class Solution:
    def stoneGameII(self, piles: list[int]) -> int:
        n = len(piles)
        # Build suffix sums for O(1) remaining stone totals
        suffix = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suffix[i] = suffix[i + 1] + piles[i]

        @lru_cache(None)
        def dp(i: int, m: int) -> int:
            # If we can take all remaining piles, take them all
            if i + 2 * m >= n:
                return suffix[i]

            # Minimise opponent's yield across all valid X
            min_opp = min(
                dp(i + x, max(m, x))
                for x in range(1, 2 * m + 1)
            )

            return suffix[i] - min_opp

        return dp(0, 1)

