        for i in range(1, len(nums)):
            if nums[i] == nums[i - 1] + 1:
                total += nums[i]
            else:
                break

        # Step 2: Store elements in a set for O(1) lookups
        seen = set(nums)

        # Step 3: Find the smallest missing integer >= total
        while total in seen:
            total += 1

        return total

