class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        m, n = len(word1), len(word2)
        # Ensure word2 is the shorter string for O(min(m, n)) space
        if m < n:
            word1, word2 = word2, word1
            m, n = n, m

        # dp[j] stores min edits to match word1 prefix with word2[:j]
        dp = list(range(n + 1))

        for i in range(1, m + 1):
            pre = dp[0]
            dp[0] = i  # Deleting all i characters from word1
            for j in range(1, n + 1):
                temp = dp[j]
                if word1[i - 1] == word2[j - 1]:
                    dp[j] = pre
                else:
                    # pre = replace, dp[j] = delete, dp[j-1] = insert
                    dp[j] = 1 + min(pre, dp[j], dp[j - 1])
                pre = temp

        return dp[n]

