class Solution:
    def partition(self, s: str) -> list[list[str]]:
        res = []
        path = []
        n = len(s)

        def is_palindrome(left: int, right: int) -> bool:
            while left < right:
                if s[left] != s[right]:
                    return False
                left += 1
                right -= 1
            return True

        def dfs(start: int) -> None:
            if start == n:
                res.append(path[:])
                return

            for end in range(start, n):
                if is_palindrome(start, end):
                    path.append(s[start:end + 1])
                    dfs(end + 1)
                    path.pop()  # backtrack

        dfs(0)
        return res

