"""

class Solution:
    def cloneGraph(self, node: 'Optional[Node]') -> 'Optional[Node]':
        if not node:
            return None

        cloned = {}

        def dfs(curr: 'Node') -> 'Node':
            # Return already cloned node if visited
            if curr in cloned:
                return cloned[curr]

            # Create clone and record in map BEFORE recurring on neighbours
            copy = Node(curr.val)
            cloned[curr] = copy

            for neighbor in curr.neighbors:
                copy.neighbors.append(dfs(neighbor))

            return copy

        return dfs(node)

