# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right

class Solution:
    def isSymmetric(self, root: Optional[TreeNode]) -> bool:
        if not root:
            return True

        def is_mirror(t1: Optional[TreeNode], t2: Optional[TreeNode]) -> bool:
            # Both null -> symmetric branch
            if not t1 and not t2:
                return True
            # One null or mismatched values -> asymmetric
            if not t1 or not t2 or t1.val != t2.val:
                return False

            # Outer pair must match AND inner pair must match
            return is_mirror(t1.left, t2.right) and is_mirror(t1.right, t2.left)

        return is_mirror(root.left, root.right)

