class Solution:
    def countPrimes(self, n: int) -> int:
        if n <= 2:
            return 0

        # is_prime[i] indicates whether i is prime
        is_prime = bytearray([1]) * n
        is_prime[0] = is_prime[1] = 0

        # Only need to check factors up to sqrt(n)
        for p in range(2, int(n**0.5) + 1):
            if is_prime[p]:
                # Start crossing off from p * p in strides of p
                is_prime[p * p : n : p] = bytearray(len(range(p * p, n, p)))

        return sum(is_prime)

