class Solution:
    def angleClock(self, hour: int, minutes: int) -> float:
        # Minute hand moves 360 / 60 = 6 degrees per minute
        minute_angle = minutes * 6.0

        # Hour hand moves 360 / 12 = 30 deg/hr + 30 / 60 = 0.5 deg/min
        hour_angle = (hour % 12) * 30.0 + minutes * 0.5

        # Absolute difference between the two hands
        diff = abs(hour_angle - minute_angle)

        # Return the smaller of the two enclosing angles
        return min(diff, 360.0 - diff)

