from collections import deque
from typing import List

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, x):
#         self.val = x
#         self.left = None
#         self.right = None

class Solution:
    def distanceK(self, root: 'TreeNode', target: 'TreeNode', k: int) -> List[int]:
        if not root or k < 0:
            return []

        # Step 1: Map child -> parent using DFS
        parents = {}
        def find_parents(node, parent):
            if not node:
                return
            parents[node] = parent
            find_parents(node.left, node)
            find_parents(node.right, node)

        find_parents(root, None)

        # Step 2: BFS out from target
        queue = deque([target])
        visited = {target}
        current_dist = 0

        while queue and current_dist < k:
            for _ in range(len(queue)):
                curr = queue.popleft()

                # Check all 3 possible directions
                for neighbour in (curr.left, curr.right, parents.get(curr)):
                    if neighbour and neighbour not in visited:
                        visited.add(neighbour)
                        queue.append(neighbour)

            current_dist += 1

        return [node.val for node in queue]

