from collections import Counter

class Solution:
    def findOriginalArray(self, changed: list[int]) -> list[int]:
        if len(changed) % 2 != 0:
            return []

        counts = Counter(changed)
        original = []

        # Sort unique keys to always process the smallest available number
        for x in sorted(counts.keys()):
            if counts[x] == 0:
                continue

            # Zero must pair with another zero
            if x == 0:
                if counts[0] % 2 != 0:
                    return []
                original.extend([0] * (counts[0] // 2))
                counts[0] = 0
            else:
                # Check if we have enough doubles
                if counts[2 * x] < counts[x]:
                    return []
                original.extend([x] * counts[x])
                counts[2 * x] -= counts[x]
                counts[x] = 0

        return original

