import heapq
from collections import deque
from typing import List

class Solution:
    def maximumSafenessFactor(self, grid: List[List[int]]) -> int:
        n = len(grid)

        # Early exit if start or end has a thief
        if grid[0][0] == 1 or grid[n - 1][n - 1] == 1:
            return 0

        # Step 1: Multi-source BFS for thief distances
        dist = [[-1] * n for _ in range(n)]
        q = deque()

        for r in range(n):
            for c in range(n):
                if grid[r][c] == 1:
                    dist[r][c] = 0
                    q.append((r, c))

        dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        while q:
            r, c = q.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and dist[nr][nc] == -1:
                    dist[nr][nc] = dist[r][c] + 1
                    q.append((nr, nc))

        # Step 2: Max-heap (Dijkstra) for maximum bottleneck path
        max_heap = [(-dist[0][0], 0, 0)]
        max_safety = [[-1] * n for _ in range(n)]
        max_safety[0][0] = dist[0][0]

        while max_heap:
            safety_neg, r, c = heapq.heappop(max_heap)
            safety = -safety_neg

            if r == n - 1 and c == n - 1:
                return safety

            if safety < max_safety[r][c]:
                continue

            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    next_safety = min(safety, dist[nr][nc])
                    if next_safety > max_safety[nr][nc]:
                        max_safety[nr][nc] = next_safety
                        heapq.heappush(max_heap, (-next_safety, nr, nc))

        return 0

