class Solution:
    def change(self, amount: int, coins: list[int]) -> int:
        dp = [0] * (amount + 1)
        dp[0] = 1  # Base case: 1 way to make 0

        # Outer loop over coins prevents permutation duplicates
        for coin in coins:
