        left, right = 0, len(arr) - 1

        # Invariant: the peak always lies in arr[left..right]
        while left < right:
            mid = left + (right - left) // 2

            if arr[mid] < arr[mid + 1]:
                # Still climbing up; peak is strictly to the right
                left = mid + 1
            else:
                # Already descending or at peak; peak is at mid or left of mid
                right = mid

        return left

