class Solution:
    def minDays(self, bloomDay: list[int], m: int, k: int) -> int:
        # Fast-fail if there aren't enough flowers in the entire garden
        if m * k > len(bloomDay):
            return -1

        def can_make(day: int) -> bool:
            bouquets = 0
            consecutive = 0
            for b in bloomDay:
                if b <= day:
                    consecutive += 1
                    if consecutive == k:
                        bouquets += 1
                        consecutive = 0
                else:
                    consecutive = 0
            return bouquets >= m

        low = min(bloomDay)
        high = max(bloomDay)
        ans = high

        while low <= high:
            mid = (low + high) // 2
            if can_make(mid):
                ans = mid
                high = mid - 1  # Try to find an earlier day
            else:
                low = mid + 1   # Need more flowers to bloom

        return ans

