from collections import deque
from typing import List

class Solution:
    def shortestSubarray(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # Build prefix sums where p[i] = sum(nums[0..i-1])
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] = p[i] + nums[i]

        min_len = float('inf')
        dq = deque()  # stores indices of p in strictly increasing order of prefix sum

        for i in range(n + 1):
            # Check if left boundary forms a valid subarray >= k
            while dq and p[i] - p[dq[0]] >= k:
                min_len = min(min_len, i - dq.popleft())

            # Maintain monotonic increasing property in dq
            while dq and p[i] <= p[dq[-1]]:
                dq.pop()

            dq.append(i)

        return min_len if min_len != float('inf') else -1

