class Solution:
    def reverseWords(self, s: str) -> str:
        chars = list(s)
        n = len(chars)

        # Helper: reverse subarray in-place
        def reverse_range(left: int, right: int) -> None:
            while left < right:
                chars[left], chars[right] = chars[right], chars[left]
                left += 1
                right -= 1

        # Step 1: reverse the entire character array
        reverse_range(0, n - 1)

        # Step 2: reverse each word back to normal
        start = 0
        for end in range(n + 1):
            if end == n or chars[end] == ' ':
                reverse_range(start, end - 1)
                start = end + 1

        # Step 3: clean up redundant spaces using two pointers
        slow = 0
        fast = 0
        while fast < n:
            # Skip spaces
            while fast < n and chars[fast] == ' ':
                fast += 1
            if fast >= n:
                break
            # Add a single space between words if not at the start
            if slow > 0:
                chars[slow] = ' '
                slow += 1
            # Copy the current word
            while fast < n and chars[fast] != ' ':
                chars[slow] = chars[fast]
                slow += 1
                fast += 1

        return "".join(chars[:slow])

