from collections import Counter

class Solution:
    def exist(self, board: list[list[str]], word: str) -> bool:
        R, C = len(board), len(board[0])
        if len(word) > R * C:
            return False

        # Pruning 1: Count frequency of characters
        board_counts = Counter(ch for row in board for ch in row)
        word_counts = Counter(word)
        for ch, count in word_counts.items():
            if board_counts[ch] < count:
                return False

        # Pruning 2: Start from rarer end to reduce branching
        if board_counts[word[0]] > board_counts[word[-1]]:
            word = word[::-1]

        def dfs(r: int, c: int, idx: int) -> bool:
            if idx == len(word):
                return True
            if not (0 <= r < R and 0 <= c < C) or board[r][c] != word[idx]:
                return False

            # In-place marking to avoid extra visited space
            temp = board[r][c]
            board[r][c] = '#'

            # Explore 4 directions
            found = (
                dfs(r + 1, c, idx + 1) or
                dfs(r - 1, c, idx + 1) or
                dfs(r, c + 1, idx + 1) or
                dfs(r, c - 1, idx + 1)
            )

            # Backtrack
            board[r][c] = temp
            return found

        for r in range(R):
            for c in range(C):
                if board[r][c] == word[0] and dfs(r, c, 0):
                    return True

        return False

