class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        s_idx, p_idx = 0, 0
        star_idx = -1
        s_tmp = -1

        while s_idx < len(s):
            # Case 1: Exact match or '?' wildcard
            if p_idx < len(p) and (p[p_idx] == s[s_idx] or p[p_idx] == '?'):
                s_idx += 1
                p_idx += 1
            # Case 2: Hit a '*' - assume it matches 0 characters for now
            elif p_idx < len(p) and p[p_idx] == '*':
                star_idx = p_idx
                s_tmp = s_idx
                p_idx += 1
            # Case 3: Mismatch, but we have a previous '*' to backtrack to
            elif star_idx != -1:
                p_idx = star_idx + 1
                s_tmp += 1
                s_idx = s_tmp
            # Case 4: Mismatch and no '*' available
            else:
                return False

        # Check if remaining characters in p are all '*'
        while p_idx < len(p) and p[p_idx] == '*':
            p_idx += 1

        return p_idx == len(p)

