class Solution:
    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> int:
        # Map of prefix_sum -> frequency on the current ancestor path
        prefix_sums = {0: 1}

        def dfs(node: Optional[TreeNode], curr_sum: int) -> int:
            if not node:
                return 0

            curr_sum += node.val
            # Number of paths ending at current node with sum == targetSum
            count = prefix_sums.get(curr_sum - targetSum, 0)

            # Record current prefix sum for children
            prefix_sums[curr_sum] = prefix_sums.get(curr_sum, 0) + 1

            # Explore left and right subtrees
            count += dfs(node.left, curr_sum)
            count += dfs(node.right, curr_sum)

            # Backtrack: remove curr_sum before leaving this branch
            prefix_sums[curr_sum] -= 1

            return count

        return dfs(root, 0)

