class Solution:
    def findKthPositive(self, arr: list[int], k: int) -> int:
        left, right = 0, len(arr) - 1

        while left <= right:
            mid = left + (right - left) // 2
            # Missing count prior to index mid
            missing = arr[mid] - (mid + 1)

            if missing < k:
                left = mid + 1
            else:
                right = mid - 1

        # left is the insertion point; arr[right] + k - (arr[right] - (right + 1)) = left + k
        return left + k

