from collections import Counter

class Solution:
    def minWindow(self, s: str, t: str) -> str:
        if not s or not t or len(s) < len(t):
            return ""

        t_counts = Counter(t)
        required = len(t_counts)
        window_counts = {}

        left = 0
        formed = 0
        # (window_length, start_idx, end_idx)
        best = (float("inf"), 0, 0)

        for right, char in enumerate(s):
            window_counts[char] = window_counts.get(char, 0) + 1

            if char in t_counts and window_counts[char] == t_counts[char]:
                formed += 1

            # Contract window from left as long as it remains valid
            while formed == required and left <= right:
                current_len = right - left + 1
                if current_len < best[0]:
                    best = (current_len, left, right)

                left_char = s[left]
                window_counts[left_char] -= 1
                if left_char in t_counts and window_counts[left_char] < t_counts[left_char]:
                    formed -= 1

                left += 1

        return "" if best[0] == float("inf") else s[best[1]:best[2] + 1]

