class Solution:
    def canCross(self, stones: list[int]) -> bool:
        # First jump must be exactly 1 unit to stones[1]
        if stones[1] != 1:
            return False

        target = stones[-1]
        # Map stone position -> set of incoming jump sizes
        dp: dict[int, set[int]] = {stone: set() for stone in stones}
        dp[1].add(1)

        for stone in stones[1:]:
            for k in dp[stone]:
                for step in (k - 1, k, k + 1):
                    if step > 0:
                        nxt = stone + step
                        if nxt == target:
                            return True
                        if nxt in dp:
                            dp[nxt].add(step)

        return len(dp[target]) > 0

