class Solution:
    def isPerfectSquare(self, num: int) -> bool:
        # 1 is a valid perfect square
        if num == 1:
            return True

        # For num > 1, sqrt(num) is strictly less than or equal to num // 2
        left, right = 2, num // 2

        while left <= right:
            mid = left + (right - left) // 2
            sq = mid * mid

            if sq == num:
                return True
            elif sq < num:
                left = mid + 1
            else:
                right = mid - 1

        return False

