class Solution:
    def ladderLength(self, beginWord: str, endWord: str, wordList: list[str]) -> int:
        word_set = set(wordList)
        if endWord not in word_set:
            return 0

        # Front and back frontiers for bidirectional BFS
        front_set = {beginWord}
        back_set = {endWord}
        # Remove beginWord and endWord from the unvisited pool
        word_set.discard(beginWord)
        word_set.discard(endWord)

        step = 1
        L = len(beginWord)

        while front_set and back_set:
            # Always expand the smaller frontier
            if len(front_set) > len(back_set):
                front_set, back_set = back_set, front_set

            next_front = set()
            for word in front_set:
                word_chars = list(word)
                for i in range(L):
                    orig_char = word_chars[i]
                    for c in 'abcdefghijklmnopqrstuvwxyz':
                        if c == orig_char:
                            continue
                        word_chars[i] = c
                        cand = "".join(word_chars)

                        if cand in back_set:
                            return step + 1
                        if cand in word_set:
                            next_front.add(cand)
                            word_set.remove(cand)
                    word_chars[i] = orig_char

            front_set = next_front
            step += 1

        return 0

find-a-safe-walk-through-a-grid.solution:
from collections import deque

class Solution:
    def findSafeWalk(self, grid: list[list[int]], health: int) -> bool:
        m, n = len(grid), len(grid[0])
        # min_damage[r][c] stores the minimum health lost to reach (r, c)
        min_damage = [[float('inf')] * n for _ in range(m)]

        min_damage[0][0] = grid[0][0]
        dq = deque([(0, 0)])

        while dq:
            r, c = dq.popleft()

            # Target reached; shortest path guaranteed upon first complete expansion
            if r == m - 1 and c == n - 1:
                return min_damage[r][c] < health

            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    cost = min_damage[r][c] + grid[nr][nc]
                    if cost < min_damage[nr][nc]:
                        min_damage[nr][nc] = cost
                        # 0-1 BFS push order: 0 cost to front, 1 cost to back
                        if grid[nr][nc] == 0:
                            dq.appendleft((nr, nc))
                        else:
                            dq.append((nr, nc))

        return min_damage[m - 1][n - 1] < health

