class Solution:
    def countPalindromes(self, s: str) -> int:
        n = len(s)
        if n < 5:
            return 0

        MOD = 1_000_000_007
        digits = [ord(ch) - ord('0') for ch in s]

        # Precompute suffix counts
        suf_cnt = [0] * 10
        suf_pairs = [[0] * 10 for _ in range(10)]
        for d in reversed(digits):
            for x in range(10):
                suf_pairs[d][x] += suf_cnt[x]
            suf_cnt[d] += 1

        pre_cnt = [0] * 10
        pre_pairs = [[0] * 10 for _ in range(10)]
        ans = 0

        for c in digits:
            # Remove current digit from suffix
            suf_cnt[c] -= 1
            for x in range(10):
                suf_pairs[c][x] -= suf_cnt[x]

            # Accumulate palindromes centered at c
            for a in range(10):
                for b in range(10):
                    if pre_pairs[a][b] and suf_pairs[b][a]:
                        ans = (ans + pre_pairs[a][b] * suf_pairs[b][a]) % MOD

            # Add current digit to prefix
            for x in range(10):
                pre_pairs[x][c] += pre_cnt[x]
            pre_cnt[c] += 1

        return ans

