class Solution:
    def cherryPickup(self, grid: list[list[int]]) -> int:
        n = len(grid)
        # dp[r1][r2] represents max cherries at current step t
        dp = [[float('-inf')] * n for _ in range(n)]
        dp[0][0] = grid[0][0]

        max_steps = 2 * n - 2
        for t in range(1, max_steps + 1):
            # Next DP layer for current step t
            next_dp = [[float('-inf')] * n for _ in range(n)]

            r1_min, r1_max = max(0, t - (n - 1)), min(n - 1, t)
            for r1 in range(r1_min, r1_max + 1):
                c1 = t - r1
                if grid[r1][c1] == -1:
                    continue
                for r2 in range(r1_min, r1_max + 1):
                    c2 = t - r2
                    if grid[r2][c2] == -1:
                        continue

                    # Cherries collected at this step
                    cherries = grid[r1][c1]
                    if r1 != r2:
                        cherries += grid[r2][c2]

                    # Check all 4 previous moves: (Down/Down, Down/Right, Right/Down, Right/Right)
                    prev_max = float('-inf')
                    for dr1 in (0, -1):
                        for dr2 in (0, -1):
                            pr1, pr2 = r1 + dr1, r2 + dr2
                            if 0 <= pr1 < n and 0 <= pr2 < n:
                                prev_max = max(prev_max, dp[pr1][pr2])

                    if prev_max != float('-inf'):
                        next_dp[r1][r2] = prev_max + cherries

            dp = next_dp

        return max(0, dp[n - 1][n - 1])

path-existence-queries-in-a-graph-ii.solution:
import bisect

class Solution:
    def pathExistenceQueries(self, n: int, nums: list[int], maxDiff: int, queries: list[list[int]]) -> list[int]:
        # Sort nodes by value
        sorted_order = sorted(range(n), key=lambda i: nums[i])
        sorted_vals = [nums[i] for i in sorted_order]
        pos = [0] * n
        for p, orig_idx in enumerate(sorted_order):
            pos[orig_idx] = p

        # Connected components based on consecutive gaps
        comp = [0] * n
        for i in range(1, n):
            comp[i] = comp[i - 1] + (1 if sorted_vals[i] - sorted_vals[i - 1] > maxDiff else 0)

        # Binary lifting table for greedy furthest right jump
        LOG = 18
        up = [[0] * n for _ in range(LOG)]
        for i in range(n):
            up[0][i] = bisect.bisect_right(sorted_vals, sorted_vals[i] + maxDiff) - 1

        for k in range(1, LOG):
            for i in range(n):
                up[k][i] = up[k - 1][up[k - 1][i]]

        ans = []
        for u, v in queries:
            if u == v:
                ans.append(0)
                continue

            pu, pv = pos[u], pos[v]
            if comp[pu] != comp[pv]:
                ans.append(-1)
                continue

            if pu > pv:
                pu, pv = pv, pu

            # If reachable in 1 jump
            if up[0][pu] >= pv:
                ans.append(1)
                continue

            # Lift pu to the furthest node strictly before pv
            steps = 0
            for k in range(LOG - 1, -1, -1):
                if up[k][pu] < pv:
                    pu = up[k][pu]
                    steps += (1 << k)

            # One last jump reaches or passes pv
            ans.append(steps + 1)

        return ans

