class Solution:
    def countSmaller(self, nums: list[int]) -> list[int]:
        # Coordinate compression: map each unique value to a 1-based rank
        ranks = {val: idx + 1 for idx, val in enumerate(sorted(set(nums)))}
        tree = [0] * (len(ranks) + 1)

        def update(idx: int, delta: int) -> None:
            while idx < len(tree):
                tree[idx] += delta
                idx += idx & (-idx)

        def query(idx: int) -> int:
            total = 0
            while idx > 0:
                total += tree[idx]
                idx -= idx & (-idx)
            return total

        res = []
        # Walk backwards so everything queried was to the right in the original array
        for num in reversed(nums):
            rank = ranks[num]
            res.append(query(rank - 1))
            update(rank, 1)

        res.reverse()
        return res

