class Solution:
    def maxEnvelopes(self, envelopes: list[list[int]]) -> int:
        if not envelopes:
            return 0

        # Sort width asc; for equal widths, sort height desc
        # This prevents picking two envelopes with identical widths
        envelopes.sort(key=lambda x: (x[0], -x[1]))

        # Standard O(n log n) LIS using patience sort
        tails = []
        for _, h in envelopes:
            idx = bisect_left(tails, h)
            if idx == len(tails):
                tails.append(h)
            else:
                tails[idx] = h

