class Solution:
    def findMinHeightTrees(self, n: int, edges: list[list[int]]) -> list[int]:
        # Base cases: small trees where all nodes are centroids
        if n <= 2:
            return list(range(n))

        # Build adjacency graph with sets for O(1) neighbor removal
        adj = [set() for _ in range(n)]
        for u, v in edges:
            adj[u].add(v)
            adj[v].add(u)

        # Collect initial leaves (nodes with only 1 edge)
        leaves = [i for i in range(n) if len(adj[i]) == 1]

        remaining_nodes = n
        # Peel outer layers until at most 2 centroids remain
        while remaining_nodes > 2:
            remaining_nodes -= len(leaves)
            new_leaves = []

            for leaf in leaves:
                # Leaf has exactly one neighbor left
                neighbor = adj[leaf].pop()
                adj[neighbor].remove(leaf)

                if len(adj[neighbor]) == 1:
                    new_leaves.append(neighbor)

            leaves = new_leaves

        return leaves

