    def shiftGrid(self, grid: list[list[int]], k: int) -> list[list[int]]:
        m, n = len(grid), len(grid[0])
        total = m * n
        k %= total

        if k == 0:
            return grid

        res = [[0] * n for _ in range(m)]
        for r in range(m):
            for c in range(n):
                new_flat = (r * n + c + k) % total
                res[new_flat // n][new_flat % n] = grid[r][c]

        return res

