class Solution:
    def maximumSubarraySum(self, nums: list[int], k: int) -> int:
        min_prefix = {}  # value -> minimum prefix sum before this value
        running_sum = 0
        max_sum = -float('inf')

        for x in nums:
            # If x could be the right endpoint, check x - k and x + k
            if x - k in min_prefix:
                max_sum = max(max_sum, running_sum + x - min_prefix[x - k])
            if x + k in min_prefix:
                max_sum = max(max_sum, running_sum + x - min_prefix[x + k])

            # Record the smallest prefix sum prior to seeing x
            if x not in min_prefix or running_sum < min_prefix[x]:
                min_prefix[x] = running_sum

            running_sum += x

        return max_sum if max_sum != -float('inf') else 0

