class Solution:
    def minimumTime(self, time: list[int], totalTrips: int) -> int:
        # Lower bound is 1; upper bound is fastest bus doing all trips alone
        left = 1
        right = min(time) * totalTrips

        while left < right:
            mid = left + (right - left) // 2

            # Calculate total trips completed by time 'mid'
            trips = sum(mid // t for t in time)

            if trips >= totalTrips:
                right = mid
            else:
                left = mid + 1

        return left

