class Solution:
    def numDecodings(self, s: str) -> int:
        if not s or s[0] == '0':
            return 0

        # prev2 = dp[i-2], prev1 = dp[i-1]
        prev2, prev1 = 1, 1

        for i in range(1, len(s)):
            current = 0

            # Single-digit decode
            if s[i] != '0':
                current += prev1

            # Two-digit decode
            two_digit = int(s[i-1:i+1])
            if 10 <= two_digit <= 26:
                current += prev2

            # If no valid decodings at this point, dead end
            if current == 0:
                return 0

            prev2, prev1 = prev1, current

        return prev1

