class Solution:
    def countValidSequences(self, n: int, k: int) -> int:
        MOD = 10**9 + 7

        # Precompute factorials up to n
        fact = [1] * (n + 1)
        inv = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = (fact[i - 1] * i) % MOD

        inv[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n - 1, -1, -1):
            inv[i] = (inv[i + 1] * (i + 1)) % MOD

        def nCr(N: int, R: int) -> int:
            if R < 0 or R > N:
                return 0
            return fact[N] * inv[R] % MOD * inv[N - R] % MOD

        # Total positive compositions of n into k parts
        total = nCr(n - 1, k - 1)

        # Complement: sequences where every element is odd
        if (n - k) % 2 != 0:
            odd_cases = 0
        else:
            # a_i = 2*x_i + 1, sum(x_i) = (n - k) // 2
            odd_cases = nCr((n + k) // 2 - 1, k - 1)

        return (total - odd_cases + MOD) % MOD

