# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right

class Solution:
    def countNodes(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0

        def get_depth(node: Optional[TreeNode]) -> int:
            depth = 0
            while node:
                depth += 1
                node = node.left
            return depth

        h = get_depth(root)
        if h == 1:
            return 1

        right_h = get_depth(root.right)

        # If right subtree left-depth hits bottom level, left subtree is completely full
        if right_h == h - 1:
            return (1 << (h - 1)) + self.countNodes(root.right)
        else:
            # Otherwise, right subtree is completely full one level shorter
            return (1 << (h - 2)) + self.countNodes(root.left)

