class Solution:
    def letterCasePermutation(self, s: str) -> list[str]:
        res = []
        chars = list(s)

        def backtrack(idx: int) -> None:
            if idx == len(chars):
                res.append("".join(chars))
                return

            if chars[idx].isalpha():
                # Branch 1: Lowercase
                chars[idx] = chars[idx].lower()
                backtrack(idx + 1)

                # Branch 2: Uppercase
                chars[idx] = chars[idx].upper()
                backtrack(idx + 1)
            else:
                # Digit: only one branch
                backtrack(idx + 1)

        backtrack(0)
        return res

