class Solution:
    def findMaxLength(self, nums: list[int]) -> int:
        # Map prefix sum to its earliest seen index
        # Base case: sum 0 at index -1 accounts for valid subarrays from index 0
        seen = {0: -1}
        curr_sum = 0
        max_len = 0

        for i, x in enumerate(nums):
            # Treat 0 as -1 and 1 as +1
            curr_sum += 1 if x == 1 else -1

            if curr_sum in seen:
                max_len = max(max_len, i - seen[curr_sum])
            else:
                # Only record the first occurrence to maximise distance
                seen[curr_sum] = i

        return max_len

