class Solution:
    def winnerSquareGame(self, n: int) -> bool:
        # dp[i] is True if the player with i stones remaining can force a win
        dp = [False] * (n + 1)

        for i in range(1, n + 1):
            k = 1
            while k * k <= i:
                # If removing k^2 leaves the other player in a losing position, we win
                if not dp[i - k * k]:
                    dp[i] = True
                    break
                k += 1

        return dp[n]

