class Solution:
    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':
        curr = root

        while curr:
            # If both targets are strictly smaller, LCA must be in the left subtree
            if p.val < curr.val and q.val < curr.val:
                curr = curr.left
            # If both targets are strictly larger, LCA must be in the right subtree
            elif p.val > curr.val and q.val > curr.val:
                curr = curr.right
            # Found the split point or one of the nodes matches curr
            else:
                return curr

        return None

