from collections import deque

class Solution:
    def longestSubarray(self, nums: list[int], limit: int) -> int:
        max_dq = deque()  # Strictly decreasing: front is max
        min_dq = deque()  # Strictly increasing: front is min
        left = 0
        max_len = 0

        for right, val in enumerate(nums):
            # Maintain decreasing order for max deque
            while max_dq and max_dq[-1] < val:
                max_dq.pop()
            max_dq.append(val)

            # Maintain increasing order for min deque
            while min_dq and min_dq[-1] > val:
                min_dq.pop()
            min_dq.append(val)

            # Shrink window until difference is valid
            while max_dq[0] - min_dq[0] > limit:
                if max_dq[0] == nums[left]:
                    max_dq.popleft()
                if min_dq[0] == nums[left]:
                    min_dq.popleft()
                left += 1

            max_len = max(max_len, right - left + 1)

        return max_len

