class Solution:
    def maxVowels(self, s: str, k: int) -> int:
        vowels = {'a', 'e', 'i', 'o', 'u'}

        # Count vowels in the initial window of size k
        curr_vowels = sum(1 for ch in s[:k] if ch in vowels)
        max_vowels = curr_vowels

        # Cannot exceed k vowels in a window of size k
        if max_vowels == k:
            return k

        # Slide the window one character at a time
        for i in range(k, len(s)):
            if s[i] in vowels:
                curr_vowels += 1
            if s[i - k] in vowels:
                curr_vowels -= 1

            if curr_vowels > max_vowels:
                max_vowels = curr_vowels
                if max_vowels == k:
                    return k

        return max_vowels

