from collections import defaultdict, deque

class Solution:
    def numBusesToDestination(self, routes: list[list[int]], source: int, target: int) -> int:
        if source == target:
            return 0

        # Inverted index: stop -> list of bus route indices
        stop_to_routes = defaultdict(list)
        for bus_idx, route in enumerate(routes):
            for stop in route:
                stop_to_routes[stop].append(bus_idx)

        if source not in stop_to_routes or target not in stop_to_routes:
            return -1

        queue = deque([source])
        visited_stops = {source}
        visited_routes = set()
        bus_count = 0

        while queue:
            bus_count += 1
            for _ in range(len(queue)):
                stop = queue.popleft()
                for bus_idx in stop_to_routes[stop]:
                    if bus_idx in visited_routes:
                        continue
                    visited_routes.add(bus_idx)

                    for next_stop in routes[bus_idx]:
                        if next_stop == target:
                            return bus_count
                        if next_stop not in visited_stops:
                            visited_stops.add(next_stop)
                            queue.append(next_stop)

        return -1

