class Solution:
    def findCheapestPrice(self, n: int, flights: list[list[int]], src: int, dst: int, k: int) -> int:
        # dist[i] holds min price from src to i using at most current flights
        dist = [float('inf')] * n
        dist[src] = 0

        # At most k stops means at most k + 1 flights
        for _ in range(k + 1):
            temp = dist.copy()
            for u, v, cost in flights:
                if dist[u] != float('inf') and dist[u] + cost < temp[v]:
                    temp[v] = dist[u] + cost
            dist = temp

        return dist[dst] if dist[dst] != float('inf') else -1

