class MyStack:

    def __init__(self):
        self.q = deque()

    def push(self, x: int) -> None:
        # Add to back, then rotate earlier elements behind it
        sz = len(self.q)
        self.q.append(x)
        for _ in range(sz):
            self.q.append(self.q.popleft())

    def pop(self) -> int:
        # Front is top of stack
        return self.q.popleft()

    def top(self) -> int:
        # Front element without removing
        return self.q[0]

    def empty(self) -> bool:
        return len(self.q) == 0

