class Solution:
    def shipWithinDays(self, weights: list[int], days: int) -> int:
        low = max(weights)
        high = sum(weights)

        def can_ship(capacity: int) -> bool:
            days_used = 1
            current_load = 0
            for w in weights:
                if current_load + w > capacity:
                    days_used += 1
                    current_load = w
                else:
                    current_load += w
            return days_used <= days

        while low < high:
            mid = low + (high - low) // 2
            if can_ship(mid):
                high = mid  # try smaller capacity
            else:
                low = mid + 1  # capacity too small

        return low

