from collections import defaultdict

class Solution:
    def findLadders(self, beginWord: str, endWord: str, wordList: list[str]) -> list[list[str]]:
        words = set(wordList)
        if endWord not in words:
            return []

        # adj will map each word to its valid shortest-path children
        adj = defaultdict(list)
        curr_level = {beginWord}
        found = False

        while curr_level and not found:
            # Words used at or before this level can't be reused deeper
            words -= curr_level
            next_level = set()

            for word in curr_level:
                word_chars = list(word)
                for i in range(len(word_chars)):
                    orig = word_chars[i]
                    for c in 'abcdefghijklmnopqrstuvwxyz':
                        if c == orig:
                            continue
                        word_chars[i] = c
                        nxt = "".join(word_chars)
                        if nxt in words:
                            if nxt == endWord:
                                found = True
                            next_level.add(nxt)
                            adj[word].append(nxt)
                    word_chars[i] = orig

            curr_level = next_level

        if not found:
            return []

        # Reconstruct paths via DFS backtracking
        res = []
        def dfs(curr: str, path: list[str]):
            if curr == endWord:
                res.append(list(path))
                return
            for nxt in adj[curr]:
                path.append(nxt)
                dfs(nxt, path)
                path.pop()

        dfs(beginWord, [beginWord])
        return res

