class Solution:
    def minFallingPathSum(self, matrix: list[list[int]]) -> int:
        n = len(matrix)
        if n == 1:
            return matrix[0][0]

        # Rolling array storing min falling sum up to previous row
        prev = list(matrix[0])

        for r in range(1, n):
            curr = [0] * n
            for c in range(n):
                left = prev[c - 1] if c > 0 else float('inf')
                mid = prev[c]
                right = prev[c + 1] if c < n - 1 else float('inf')

                curr[c] = matrix[r][c] + min(left, mid, right)
            prev = curr

        return min(prev)

