class Solution:
    def longestCommonPrefix(self, arr1: list[int], arr2: list[int]) -> int:
        prefixes = set()

        # Add all prefixes of arr1 numbers into the set
        for val in arr1:
            curr = val
            while curr > 0:
                prefixes.add(curr)
                curr //= 10

        max_len = 0
        # Check prefixes of arr2 from longest to shortest
        for val in arr2:
            curr = val
            while curr > 0:
                if curr in prefixes:
                    # Digits count: len(str(curr)) or floor(log10(curr)) + 1
                    max_len = max(max_len, len(str(curr)))
                    break  # Any further division gives shorter prefixes
