class Solution:
    def maxAreaOfIsland(self, grid: list[list[int]]) -> int:
        rows, cols = len(grid), len(grid[0])
        max_area = 0

        def dfs(r: int, c: int) -> int:
            # Base case: out of bounds or water/already visited
            if not (0 <= r < rows and 0 <= c < cols and grid[r][c] == 1):
                return 0

            # Sink the island to prevent cycles
            grid[r][c] = 0

            # Sum current cell + all 4 directions
            return (1 + dfs(r + 1, c) 
                      + dfs(r - 1, c) 
                      + dfs(r, c + 1) 
                      + dfs(r, c - 1))

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 1:
                    max_area = max(max_area, dfs(r, c))

        return max_area

