class FenwickTree:
    def __init__(self, size: int):
        self.tree = [0] * (size + 1)

    def update(self, idx: int, delta: int):
        while idx < len(self.tree):
            self.tree[idx] += delta
            idx += idx & (-idx)

    def query(self, idx: int) -> int:
        res = 0
        while idx > 0:
            res += self.tree[idx]
            idx -= idx & (-idx)
        return res

class Solution:
    def countSubarrays(self, nums: list[int], target: int) -> int:
        n = len(nums)
        # Offset to map prefix sums from [-n, n] to [1, 2n + 1]
        offset = n + 1
        bit = FenwickTree(2 * n + 2)

        # prefix sum 0 is seen once at the start
        bit.update(offset, 1)

        curr_sum = 0
        ans = 0

        for x in nums:
            curr_sum += 1 if x == target else -1
            shifted = curr_sum + offset
            # Count prefix sums strictly less than shifted (i.e. <= shifted - 1)
            ans += bit.query(shifted - 1)
            bit.update(shifted, 1)

        return ans

number-of-zigzag-arrays-ii.solution:
class Solution:
    def countZigZag(self, n: int, l: int, r: int) -> int:
        MOD = 10**9 + 7
        m = r - l + 1
        dim = 2 * m

        # Matrix multiplication helper
        def mat_mul(A, B):
            C = [[0] * dim for _ in range(dim)]
            for i in range(dim):
                for k in range(dim):
                    if not A[i][k]:
                        continue
                    for j in range(dim):
                        C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
            return C

        # Matrix exponentiation helper
        def mat_pow(mat, p):
            res = [[1 if i == j else 0 for j in range(dim)] for i in range(dim)]
            base = mat
            while p > 0:
                if p & 1:
                    res = mat_mul(res, base)
                base = mat_mul(base, base)
                p >>= 1
            return res

        # Build transition matrix T of size 2m x 2m
        # State 0..m-1: (val, UP); State m..2m-1: (val, DOWN)
        T = [[0] * dim for _ in range(dim)]
        for x in range(m):
            # From UP(x), can go DOWN to any y < x
            for y in range(x):
                T[x][m + y] = 1
            # From DOWN(x), can go UP to any y > x
            for y in range(x + 1, m):
                T[m + x][y] = 1

        # Initial vector for n = 2
        # UP: count of x' < x is x; DOWN: count of x' > x is m - 1 - x
        v = [0] * dim
        for x in range(m):
            v[x] = x
            v[m + x] = m - 1 - x

        # Apply T^(n - 2)
        Tn = mat_pow(T, n - 2)

        # Multiply v (1 x dim) by Tn (dim x dim)
        ans = 0
        for j in range(dim):
            val = 0
            for i in range(dim):
                val = (val + v[i] * Tn[i][j]) % MOD
            ans = (ans + val) % MOD

        return ans

