class Solution:
    def circularArrayLoop(self, nums: list[int]) -> bool:
        n = len(nums)

        def get_next(i: int) -> int:
            return (i + nums[i]) % n

        for i in range(n):
            if nums[i] == 0:
                continue

            slow = i
            fast = i
            is_forward = nums[i] > 0

            while True:
                # Check slow next
                next_slow = get_next(slow)
                if (nums[next_slow] > 0) != is_forward or nums[next_slow] == 0:
                    break
                slow = next_slow

                # Check fast step 1
                next_fast1 = get_next(fast)
                if (nums[next_fast1] > 0) != is_forward or nums[next_fast1] == 0:
                    break
                # Check fast step 2
                next_fast2 = get_next(next_fast1)
                if (nums[next_fast2] > 0) != is_forward or nums[next_fast2] == 0:
                    break
                fast = next_fast2

                if slow == fast:
                    # Reject 1-element self-loops
                    if slow == get_next(slow):
                        break
                    return True

            # Clean up dead-end path in-place
            curr = i
            while (nums[curr] > 0) == is_forward and nums[curr] != 0:
                nxt = get_next(curr)
                nums[curr] = 0
                curr = nxt

        return False

