class Solution:
    def numberOfGoodPaths(self, vals: List[int], edges: List[List[int]]) -> int:
        n = len(vals)
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        # Group nodes by their value
        val_to_nodes = collections.defaultdict(list)
        for i, val in enumerate(vals):
            val_to_nodes[val].append(i)

        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x: int, y: int) -> None:
            rx, ry = find(x), find(y)
            if rx != ry:
                if rank[rx] < rank[ry]:
                    rx, ry = ry, rx
                parent[ry] = rx
                if rank[rx] == rank[ry]:
                    rank[rx] += 1

        ans = n  # Every single node is a good path

        # Process values in ascending order
        for val in sorted(val_to_nodes.keys()):
            nodes = val_to_nodes[val]

            # Union current nodes with smaller/equal neighbours
            for u in nodes:
                for nei in adj[u]:
                    if vals[nei] <= val:
                        union(u, nei)

            # Count how many nodes of value `val` share the same root
            root_count = collections.defaultdict(int)
            for u in nodes:
                root_count[find(u)] += 1

            # k nodes in the same component produce k*(k-1)//2 new good paths
            for count in root_count.values():
                ans += count * (count - 1) // 2

        return ans

