class Solution:
    def minScore(self, n: int, roads: list[list[int]]) -> int:
        # Build graph
        adj = [[] for _ in range(n + 1)]
        for u, v, d in roads:
            adj[u].append((v, d))
            adj[v].append((u, d))

        min_score = float('inf')
        visited = [False] * (n + 1)
        queue = collections.deque([1])
        visited[1] = True

        while queue:
            curr = queue.popleft()
            for neighbour, dist in adj[curr]:
                min_score = min(min_score, dist)
                if not visited[neighbour]:
                    visited[neighbour] = True
                    queue.append(neighbour)

        return min_score

