class Solution:
    def pathsWithMaxScore(self, board: List[str]) -> List[int]:
        n = len(board)
        MOD = 10**9 + 7

        # dp[r][c] = [max_score, path_count]
        dp = [[[ -1, 0 ] for _ in range(n)] for _ in range(n)]
        dp[n - 1][n - 1] = [0, 1]

        for r in range(n - 1, -1, -1):
            for c in range(n - 1, -1, -1):
                if (r == n - 1 and c == n - 1) or board[r][c] == 'X':
                    continue

                max_prev_score = -1
                total_ways = 0

                # Transitions from down, right, and down-right
                for dr, dc in [(1, 0), (0, 1), (1, 1)]:
                    nr, nc = r + dr, c + dc
                    if nr < n and nc < n and dp[nr][nc][1] > 0:
                        prev_score, prev_ways = dp[nr][nc]
                        if prev_score > max_prev_score:
                            max_prev_score = prev_score
                            total_ways = prev_ways
                        elif prev_score == max_prev_score:
                            total_ways = (total_ways + prev_ways) % MOD

                if total_ways > 0:
                    val = 0 if board[r][c] == 'E' else int(board[r][c])
                    dp[r][c] = [max_prev_score + val, total_ways]

        res_score, res_ways = dp[0][0]
        return [res_score, res_ways] if res_ways > 0 else [0, 0]

longest-increasing-subsequence-ii.solution:
class Solution:
    def lengthOfLIS(self, nums: list[int], k: int) -> int:
        m = max(nums)
        # Iterative Segment Tree for range max query over [1, m]
        tree = [0] * (2 * (m + 1))

        def query(l: int, r: int) -> int:
            res = 0
            l += m + 1
            r += m + 1
            while l <= r:
                if l % 2 == 1:
                    res = max(res, tree[l])
                    l += 1
                if r % 2 == 0:
                    res = max(res, tree[r])
                    r -= 1
                l //= 2
                r //= 2
            return res

        def update(idx: int, val: int) -> None:
            idx += m + 1
            if val <= tree[idx]:
                return
            tree[idx] = val
            while idx > 1:
                idx //= 2
                tree[idx] = max(tree[2 * idx], tree[2 * idx + 1])

        for x in nums:
            left = max(1, x - k)
            right = x - 1
            best = query(left, right) if left <= right else 0
            update(x, best + 1)

        return tree[1]

