class Solution:
    def numberOfSubarrays(self, nums: list[int], k: int) -> int:
        def at_most(goal: int) -> int:
            if goal < 0:
                return 0

            left = 0
            odds = 0
            count = 0

            for right in range(len(nums)):
                odds += nums[right] & 1

                while odds > goal:
                    odds -= nums[left] & 1
                    left += 1

                count += right - left + 1

            return count

        return at_most(k) - at_most(k - 1)

