        # If we can take only 1s, return k
        if k <= numOnes:
            return k

        # If we can take all 1s and some/all 0s, sum is just numOnes
        if k <= numOnes + numZeros:
            return numOnes

        # Otherwise, we are forced to take (k - numOnes - numZeros) of -1s
        neg_ones_to_take = k - numOnes - numZeros
        return numOnes - neg_ones_to_take

