class Solution:
    def maximumCandies(self, candies: list[int], k: int) -> int:
        # If total candies can't even give 1 candy to each child, return 0
        if sum(candies) < k:
            return 0

        low, high = 1, max(candies)
        ans = 0

        while low <= high:
            mid = (low + high) // 2

            # Count how many piles of size mid we can create
            piles = sum(c // mid for c in candies)

            if piles >= k:
                ans = mid        # mid works, try searching for a bigger pile size
                low = mid + 1
            else:
                high = mid - 1   # mid is too greedy, try a smaller size

        return ans

