class Solution:
    def shortestPalindrome(self, s: str) -> str:
        if not s:
            return s

        rev_s = s[::-1]
        concat = s + '#' + rev_s
        n = len(concat)
        pi = [0] * n

        # Build KMP prefix function
        for i in range(1, n):
            j = pi[i - 1]
            while j > 0 and concat[i] != concat[j]:
                j = pi[j - 1]
            if concat[i] == concat[j]:
                j += 1
            pi[i] = j

        # pi[-1] gives length of longest palindromic prefix
        pal_len = pi[-1]
        add_on = rev_s[:len(s) - pal_len]
        return add_on + s

