from collections import Counter

class Solution:
    def kthPalindrome(self, s: str, k: int) -> str:
        n = len(s)
        counts = Counter(s)

        # Identify the middle character for odd lengths
        mid_char = ""
        half_counts = {}
        for ch, count in counts.items():
            if count % 2 == 1:
                mid_char = ch
            half_counts[ch] = count // 2

        cap = k

        def comb_capped(n_items: int, r_items: int, limit: int) -> int:
            if r_items < 0 or r_items > n_items:
                return 0
            r_items = min(r_items, n_items - r_items)
            ans = 1
            for i in range(r_items):
                ans = ans * (n_items - i) // (i + 1)
                if ans >= limit:
                    return limit
            return ans

        def multiset_perms(freq_list, limit: int) -> int:
            total = 1
            rem = sum(freq_list)
            for c in freq_list:
                if c <= 0:
                    continue
                total *= comb_capped(rem, c, limit)
                if total >= limit:
                    return limit
                rem -= c
            return total

        # Early exit if total distinct palindromes < k
        if multiset_perms(list(half_counts.values()), cap) < k:
            return ""

        first_half = []
        half_len = n // 2
        distinct_chars = sorted(half_counts.keys())

        for _ in range(half_len):
            for ch in distinct_chars:
                if half_counts[ch] == 0:
                    continue

                # Tentatively pick ch
                half_counts[ch] -= 1
                ways = multiset_perms(list(half_counts.values()), k)

                if ways >= k:
                    first_half.append(ch)
                    break
                else:
                    k -= ways
                    half_counts[ch] += 1

        half_str = "".join(first_half)
        return half_str + mid_char + half_str[::-1]

