from collections import defaultdict, OrderedDict

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.min_freq = 0
        # key -> (value, freq)
        self.key_map = {}
        # freq -> OrderedDict of {key: None}
        self.freq_map = defaultdict(OrderedDict)

    def _update_freq(self, key: int) -> None:
        val, freq = self.key_map[key]
        # Remove key from current frequency bucket
        del self.freq_map[freq][key]
        if not self.freq_map[freq]:
            del self.freq_map[freq]
            if self.min_freq == freq:
                self.min_freq += 1
        # Insert key into next frequency bucket
        self.freq_map[freq + 1][key] = None
        self.key_map[key] = (val, freq + 1)

    def get(self, key: int) -> int:
        if key not in self.key_map:
            return -1
        self._update_freq(key)
        return self.key_map[key][0]

    def put(self, key: int, value: int) -> None:
        if self.capacity <= 0:
            return

        if key in self.key_map:
            _, freq = self.key_map[key]
            self.key_map[key] = (value, freq)
            self._update_freq(key)
            return

        if len(self.key_map) >= self.capacity:
            # Evict LRU key from min_freq bucket
            evict_key, _ = self.freq_map[self.min_freq].popitem(last=False)
            del self.key_map[evict_key]

        # Fresh key starts at freq 1
        self.key_map[key] = (value, 1)
        self.freq_map[1][key] = None
        self.min_freq = 1

