class Solution:
    def uniqueMorseRepresentations(self, words: list[str]) -> int:
        # Lookup table indexed by ord(char) - ord('a')
        morse = [
            ".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..",
            ".---", "-.-", ".-..", "--", "-.", "---", ".--.", "--.-", ".-.",
            "...", "-", "..-", "...-", ".--", "-..-", "-.--", "--.."
        ]

        seen = set()
        base = ord('a')

        for word in words:
            # Build morse representation for the current word
            code = "".join(morse[ord(ch) - base] for ch in word)
            seen.add(code)

        return len(seen)

