# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right

class Solution:
    def rangeSumBST(self, root: Optional[TreeNode], low: int, high: int) -> int:
        if not root:
            return 0

        # If current value is below range, entire left subtree is out of range
        if root.val < low:
            return self.rangeSumBST(root.right, low, high)

        # If current value is above range, entire right subtree is out of range
        if root.val > high:
            return self.rangeSumBST(root.left, low, high)

        # Current value is within [low, high], collect it and explore both branches
        return root.val + self.rangeSumBST(root.left, low, high) + self.rangeSumBST(root.right, low, high)

