class Solution:
    def numOfUnplacedFruits(self, fruits: list[int], baskets: list[int]) -> int:
        n = len(baskets)
        tree = [0] * (4 * n)

        def build(node: int, l: int, r: int) -> None:
            if l == r:
                tree[node] = baskets[l]
                return
            mid = (l + r) // 2
            build(2 * node, l, mid)
            build(2 * node + 1, mid + 1, r)
            tree[node] = max(tree[2 * node], tree[2 * node + 1])

        def place(node: int, l: int, r: int, val: int) -> bool:
            if tree[node] < val:
                return False
            if l == r:
                tree[node] = -1  # Mark basket as used
                return True
            mid = (l + r) // 2
            # Greedily search leftmost valid basket
            if tree[2 * node] >= val:
                res = place(2 * node, l, mid, val)
            else:
                res = place(2 * node + 1, mid + 1, r, val)
            tree[node] = max(tree[2 * node], tree[2 * node + 1])
            return res

        build(1, 0, n - 1)
        unplaced = 0
        for f in fruits:
            if not place(1, 0, n - 1, f):
                unplaced += 1

        return unplaced

