class Solution:
    def calculate(self, s: str) -> int:
        stack = []
        curr_num = 0
        last_op = '+'

        for i, ch in enumerate(s):
            if ch.isdigit():
                curr_num = curr_num * 10 + int(ch)

            # Trigger evaluation on operator or end of string (ignore spaces)
            if (not ch.isdigit() and ch != ' ') or i == len(s) - 1:
                if last_op == '+':
                    stack.append(curr_num)
                elif last_op == '-':
                    stack.append(-curr_num)
                elif last_op == '*':
                    stack.append(stack.pop() * curr_num)
                elif last_op == '/':
                    # int(a / b) truncates towards zero in Python
                    stack.append(int(stack.pop() / curr_num))

                last_op = ch
                curr_num = 0

        return sum(stack)

