        max_len = 0

        for right, val in enumerate(nums):
            counts[val] = counts.get(val, 0) + 1

            # Only the current incoming element could have breached frequency k
            while counts[val] > k:
                counts[nums[left]] -= 1
                left += 1

            max_len = max(max_len, right - left + 1)

        return max_len

