class Solution:
    def maxDistance(self, position: list[int], m: int) -> int:
        position.sort()

        def can_place(force: int) -> bool:
            count = 1
            last_pos = position[0]

            for pos in position[1:]:
                if pos - last_pos >= force:
                    count += 1
                    last_pos = pos
                    if count >= m:
                        return True
            return False

        low = 1
        high = position[-1] - position[0]
        ans = 1

        while low <= high:
            mid = (low + high) // 2
            if can_place(mid):
                ans = mid
                low = mid + 1  # Try to maximise force
            else:
                high = mid - 1 # Force is too large, reduce it

        return ans

