from operator import xor

class Solution:
    def longestSubsequence(self, nums: list[int]) -> int:
        # Total XOR of all elements
        total_xor = reduce(xor, nums, 0)

        # If the whole array has non-zero XOR, take all elements
        if total_xor != 0:
            return len(nums)

        # If total XOR is 0, can we drop one non-zero element?
        if any(x != 0 for x in nums):
            return len(nums) - 1

        # All elements are 0, impossible to get non-zero XOR
        return 0

