class Solution:
    def isNStraightHand(self, hand: list[int], groupSize: int) -> bool:
        if len(hand) % groupSize != 0:
            return False

        counts = Counter(hand)

        # Process keys in ascending order
        for card in sorted(counts):
            k = counts[card]
            if k > 0:
                # Card must start k groups of size groupSize
                for next_card in range(card, card + groupSize):
                    if counts[next_card] < k:
                        return False
                    counts[next_card] -= k

        return True

