from collections import Counter
from typing import List

class Solution:
    def largestAlmostMissing(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # Case 1: Entire array is the only subarray of size k
        if k == n:
            return max(nums)

        freq = Counter(nums)

        # Case 2: Subarrays of size 1
        if k == 1:
            uniques = [val for val, count in freq.items() if count == 1]
            return max(uniques) if uniques else -1

        # Case 3: 1 < k < n -> only boundary elements can appear in exactly 1 window
        ans = -1
        if freq[nums[0]] == 1:
            ans = max(ans, nums[0])
        if freq[nums[n - 1]] == 1:
            ans = max(ans, nums[n - 1])

        return ans

strong-password-checker.solution:
class Solution:
    def strongPasswordChecker(self, password: str) -> int:
        n = len(password)

        # 1. Missing character types
        has_lower = any(c.islower() for c in password)
        has_upper = any(c.isupper() for c in password)
        has_digit = any(c.isdigit() for c in password)
        missing_types = (not has_lower) + (not has_upper) + (not has_digit)

        # 2. Identify repeat runs of length >= 3
        runs = []
        i = 0
        while i < n:
            j = i
            while j < n and password[j] == password[i]:
                j += 1
            run_len = j - i
            if run_len >= 3:
                runs.append(run_len)
            i = j

        # Case 1: Short password (n < 6)
        if n < 6:
            return max(6 - n, missing_types)

        # Case 2: Ideal length (6 <= n <= 20)
        if n <= 20:
            replace_needed = sum(length // 3 for length in runs)
            return max(missing_types, replace_needed)

        # Case 3: Long password (n > 20)
        deletes_needed = n - 20
        leftover_deletes = deletes_needed

        # Priority 1: L % 3 == 0, 1 delete saves 1 replace
        for idx in range(len(runs)):
            if leftover_deletes >= 1 and runs[idx] % 3 == 0:
                runs[idx] -= 1
                leftover_deletes -= 1

        # Priority 2: L % 3 == 1, 2 deletes save 1 replace
        for idx in range(len(runs)):
            if leftover_deletes >= 2 and runs[idx] % 3 == 1:
                runs[idx] -= 2
                leftover_deletes -= 2

        # Priority 3: any remaining deletes, 3 deletes save 1 replace
        for idx in range(len(runs)):
            if leftover_deletes > 0 and runs[idx] >= 3:
                del_count = min(leftover_deletes, runs[idx] - 2)
                runs[idx] -= del_count
                leftover_deletes -= del_count

        replace_needed = sum(length // 3 for length in runs)
        return deletes_needed + max(missing_types, replace_needed)

