class Solution:
    def longestPalindromeSubseq(self, s: str) -> int:
        n = len(s)
        # dp[j] represents LPS length for substring s[i..j]
        dp = [0] * n

        # Traverse backwards so subproblems (i+1) are ready
        for i in range(n - 1, -1, -1):
            dp[i] = 1
            prev = 0  # Represents dp[i+1][j-1]
            for j in range(i + 1, n):
                temp = dp[j]
                if s[i] == s[j]:
                    dp[j] = prev + 2
                else:
                    dp[j] = max(dp[j], dp[j - 1])
                prev = temp

        return dp[n - 1]

