class Solution:
    def maximumSubarraySum(self, nums: list[int], k: int) -> int:
        counts = {}
        window_sum = 0
        max_sum = 0

        for i, val in enumerate(nums):
            # Add current element to window
            window_sum += val
            counts[val] = counts.get(val, 0) + 1

            # Evict element that fell outside window
            if i >= k:
                out = nums[i - k]
                window_sum -= out
                counts[out] -= 1
                if counts[out] == 0:
                    del counts[out]

            # Evaluate valid window of exact length k
            if i >= k - 1 and len(counts) == k:
                if window_sum > max_sum:
                    max_sum = window_sum

        return max_sum

