class Solution:
    def canVisitAllRooms(self, rooms: list[list[int]]) -> bool:
        n = len(rooms)
        visited = [False] * n
        visited[0] = True
        visited_count = 1
        stack = [0]

        while stack:
            curr = stack.pop()
            for nxt in rooms[curr]:
                if not visited[nxt]:
                    visited[nxt] = True
                    visited_count += 1
                    if visited_count == n:
                        return True
