class Solution:
    def countDigitOne(self, n: int) -> int:
        if n <= 0:
            return 0

        total_ones = 0
        k = 1  # Current place value: 1, 10, 100, ...

        while k <= n:
            higher = n // (k * 10)
            curr = (n // k) % 10
            lower = n % k

            if curr == 0:
                total_ones += higher * k
            elif curr == 1:
                total_ones += higher * k + lower + 1
            else:
                total_ones += (higher + 1) * k

            k *= 10

        return total_ones

