class Solution:
    def isUgly(self, n: int) -> bool:
        # Ugly numbers must be strictly positive
        if n <= 0:
            return False

        # Strip out all factors of 2, 3, and 5
        for prime in (2, 3, 5):
            while n % prime == 0:
                n //= prime

        # If only 2, 3, and 5 were factors, n collapses to 1
        return n == 1

