import math
from functools import lru_cache

class Solution:
    def subsequencePairAfterGCD(self, nums: list[int]) -> int:
        MOD = 1_000_000_007
        n = len(nums)

        @lru_cache(maxsize=None)
        def dp(i: int, g1: int, g2: int) -> int:
            if i == n:
                return 1 if (g1 > 0 and g1 == g2) else 0

            # Choice 1: Skip nums[i]
            ans = dp(i + 1, g1, g2)

            # Choice 2: Add to seq1
            ng1 = nums[i] if g1 == 0 else math.gcd(g1, nums[i])
            ans = (ans + dp(i + 1, ng1, g2)) % MOD

            # Choice 3: Add to seq2
            ng2 = nums[i] if g2 == 0 else math.gcd(g2, nums[i])
            ans = (ans + dp(i + 1, g1, ng2)) % MOD

            return ans

        return dp(0, 0, 0)

