class Solution:
    def numRollsToTarget(self, n: int, k: int, target: int) -> int:
        # Impossible sums shortcut
        if target < n or target > n * k:
            return 0

        MOD = 10**9 + 7
        dp = [0] * (target + 1)
        dp[0] = 1  # 0 dice sum to 0 in exactly 1 way

        for die in range(1, n + 1):
            next_dp = [0] * (target + 1)
            # Calculate bounds to avoid pointless iterations
            min_prev = max(0, die - 1)
            max_prev = min(target, (die - 1) * k)

            for s in range(min_prev, max_prev + 1):
                if dp[s] == 0:
                    continue
                for face in range(1, k + 1):
                    if s + face <= target:
                        next_dp[s + face] = (next_dp[s + face] + dp[s]) % MOD
                    else:
                        break  # face is increasing, later sums will also exceed target
            dp = next_dp

        return dp[target]

