import random

def wiggleSort(nums: list[int]) -> None:
    """
    Do not return anything, modify nums in-place instead.
    """
    n = len(nums)
    if n <= 1:
        return

    # Quickselect to find the median in O(n) expected time
    def quickselect(left: int, right: int, k: int) -> int:
        if left == right:
            return nums[left]

        pivot_idx = random.randint(left, right)
        pivot_val = nums[pivot_idx]
        nums[pivot_idx], nums[right] = nums[right], nums[pivot_idx]

        store_idx = left
        for i in range(left, right):
            if nums[i] < pivot_val:
                nums[store_idx], nums[i] = nums[i], nums[store_idx]
                store_idx += 1
        nums[store_idx], nums[right] = nums[right], nums[store_idx]

        if k == store_idx:
            return nums[store_idx]
        elif k < store_idx:
            return quickselect(left, store_idx - 1, k)
        else:
            return quickselect(store_idx + 1, right, k)

    median = quickselect(0, n - 1, n // 2)

    # Virtual indexing function: maps 0, 1, 2... to 1, 3, 5..., 0, 2, 4...
    # (n | 1) rounds n up to the next odd number if even
    def A(i: int) -> int:
        return (1 + 2 * i) % (n | 1)

    # 3-way partitioning (Dutch National Flag) on mapped indices
    low, mid, high = 0, 0, n - 1
    while mid <= high:
        if nums[A(mid)] > median:
            nums[A(low)], nums[A(mid)] = nums[A(mid)], nums[A(low)]
            low += 1
            mid += 1
        elif nums[A(mid)] < median:
            nums[A(mid)], nums[A(high)] = nums[A(high)], nums[A(mid)]
            high -= 1
        else:
            mid += 1

