from collections import deque

class Solution:
    def minMutation(self, startGene: str, endGene: str, bank: list[str]) -> int:
        bank_set = set(bank)

        # Target must be in the bank
        if endGene not in bank_set:
            return -1

        # BFS queue stores (gene_string, mutation_count)
        queue = deque([(startGene, 0)])
        visited = {startGene}
        chars = ('A', 'C', 'G', 'T')

        while queue:
            curr, steps = queue.popleft()

            if curr == endGene:
                return steps

            # Generate all 8 * 3 = 24 single-character mutations
            for i in range(len(curr)):
                for c in chars:
                    if c != curr[i]:
                        nxt = curr[:i] + c + curr[i+1:]
                        if nxt in bank_set and nxt not in visited:
                            visited.add(nxt)
                            queue.append((nxt, steps + 1))

        return -1

