class Solution:
    def removeStones(self, stones: List[List[int]]) -> int:
        parent = {}
        self.components = 0

        def find(x: int) -> int:
            if x not in parent:
                parent[x] = x
                self.components += 1
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x: int, y: int) -> None:
            root_x, root_y = find(x), find(y)
            if root_x != root_y:
                parent[root_x] = root_y
                self.components -= 1

        for r, c in stones:
            # Use ~c to differentiate column indices from row indices
            union(r, ~c)

        return len(stones) - self.components

