from collections import defaultdict
from typing import List

class Solution:
    def accountsMerge(self, accounts: List[List[str]]) -> List[List[str]]:
        graph = defaultdict(list)
        email_to_name = {}

        # Build the graph and name lookup
        for acc in accounts:
            name = acc[0]
            first_email = acc[1]
            for email in acc[1:]:
                email_to_name[email] = name
                # Connect first email with current email (bidirectional)
                graph[first_email].append(email)
                graph[email].append(first_email)

        visited = set()
        merged_accounts = []

        # DFS to collect all emails in the same component
        def dfs(email: str, component: List[str]) -> None:
            visited.add(email)
            component.append(email)
            for neighbor in graph[email]:
                if neighbor not in visited:
                    dfs(neighbor, component)

        for email in graph:
            if email not in visited:
                component = []
                dfs(email, component)
                # Return format requires name first, then sorted emails
                merged_accounts.append([email_to_name[email]] + sorted(component))

        return merged_accounts

