import bisect

class SnapshotArray:
    def __init__(self, length: int):
        # Each index holds a list of (snap_id, val) pairs
        self.history = [[(0, 0)] for _ in range(length)]
        self.snap_id = 0

    def set(self, index: int, val: int) -> None:
        # Overwrite if modified in the current snapshot, else append
        if self.history[index][-1][0] == self.snap_id:
            self.history[index][-1] = (self.snap_id, val)
        else:
            self.history[index].append((self.snap_id, val))

    def snap(self) -> int:
        self.snap_id += 1
        return self.snap_id - 1

    def get(self, index: int, snap_id: int) -> int:
        records = self.history[index]
        # Find rightmost entry with record_snap_id <= snap_id
        # (snap_id, float('inf')) ensures we jump past any record with == snap_id
        idx = bisect.bisect_right(records, (snap_id, float('inf'))) - 1
        return records[idx][1]

