        for idx in range(1, n):
            next2 = dp[i2] * 2
            next3 = dp[i3] * 3
            next5 = dp[i5] * 5

            chosen = min(next2, next3, next5)
            dp[idx] = chosen

            # Independent ifs to deduplicate matching multiples (e.g. 6)
            if chosen == next2:
                i2 += 1
            if chosen == next3:
                i3 += 1
            if chosen == next5:
                i5 += 1

        return dp[-1]

