class Solution:
    def kthSmallest(self, matrix: list[list[int]], k: int) -> int:
        n = len(matrix)

        def count_less_or_equal(target: int) -> int:
            # Staircase walk starting from bottom-left corner
            count = 0
            row, col = n - 1, 0
            while row >= 0 and col < n:
                if matrix[row][col] <= target:
                    # All items from row 0 to row in this col are <= target
                    count += row + 1
                    col += 1
                else:
                    row -= 1
            return count

        low, high = matrix[0][0], matrix[n - 1][n - 1]
        while low < high:
            mid = low + (high - low) // 2
            if count_less_or_equal(mid) < k:
                low = mid + 1
            else:
                high = mid

        return low

