class Solution:
    def oddEvenJumps(self, arr: list[int]) -> int:
        n = len(arr)
        if n <= 1:
            return n

        def get_next_jumps(indices: list[int]) -> list[int | None]:
            next_jump = [None] * n
            stack = []
            for idx in indices:
                while stack and stack[-1] < idx:
                    next_jump[stack.pop()] = idx
                stack.append(idx)
            return next_jump

        # Odd jump: smallest arr[j] >= arr[i], tie-break with smaller index
        sorted_by_val_asc = sorted(range(n), key=lambda i: (arr[i], i))
        next_higher = get_next_jumps(sorted_by_val_asc)

        # Even jump: largest arr[j] <= arr[i], tie-break with smaller index
        sorted_by_val_desc = sorted(range(n), key=lambda i: (-arr[i], i))
        next_lower = get_next_jumps(sorted_by_val_desc)

        higher = [False] * n
        lower = [False] * n
        higher[-1] = lower[-1] = True

        for i in range(n - 2, -1, -1):
            if next_higher[i] is not None:
                higher[i] = lower[next_higher[i]]
            if next_lower[i] is not None:
                lower[i] = higher[next_lower[i]]

        return sum(higher)

