from collections import deque

class Solution:
    def shortestPath(self, grid: list[list[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])

        # Base case: already at destination
        if m == 1 and n == 1:
            return 0

        # Shortcut: if k allows a direct Manhattan path, return it directly
        if k >= m + n - 2:
            return m + n - 2

        # queue stores tuples of (row, col, remaining_k, steps)
        queue = deque([(0, 0, k, 0)])
        # visited[r][c] stores the highest remaining_k seen at (r, c)
        visited = [[-1] * n for _ in range(m)]
        visited[0][0] = k

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while queue:
            r, c, rem_k, steps = queue.popleft()

            if r == m - 1 and c == n - 1:
                return steps

            for dr, dc in directions:
                nr, nc = r + dr, c + dc

                if 0 <= nr < m and 0 <= nc < n:
                    next_k = rem_k - grid[nr][nc]
                    # Only proceed if we can eliminate the obstacle and it gives a strictly better k
                    if next_k >= 0 and next_k > visited[nr][nc]:
                        visited[nr][nc] = next_k
                        queue.append((nr, nc, next_k, steps + 1))

        return -1

