        while i < n or j < n:
            # Skip blank spaces in start
            while i < n and start[i] == '_':
                i += 1
            # Skip blank spaces in target
            while j < n and target[j] == '_':
                j += 1

            # If one reached the end, both must have reached the end
            if i == n or j == n:
                return i == n and j == n

            # Piece identity must match
            if start[i] != target[j]:
                return False

            # Movement direction constraints
            if start[i] == 'L' and i < j:
                return False
            if start[i] == 'R' and i > j:
                return False

            i += 1
            j += 1

        return True

