class Solution:
    def minZeroArray(self, nums: list[int], queries: list[list[int]]) -> int:
        # Check if already a zero array
        if all(x == 0 for x in nums):
            return 0

        n = len(nums)
        m = len(queries)

        def can_zero(k: int) -> bool:
            # Difference array of size n + 1
            diff = [0] * (n + 1)
            for i in range(k):
                l, r, val = queries[i]
                diff[l] += val
                diff[r + 1] -= val

            running_sum = 0
            for i in range(n):
                running_sum += diff[i]
                if running_sum < nums[i]:
                    return False
            return True

        low, high = 1, m
        ans = -1

        while low <= high:
            mid = (low + high) // 2
            if can_zero(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1

        return ans

