import math

class Solution:
    def repairCars(self, ranks: list[int], cars: int) -> int:
        low = 1
        # Upper bound: best mechanic repairs all cars alone
        high = min(ranks) * cars * cars

        def can_repair(time: int) -> bool:
            total = 0
            for r in ranks:
                total += math.isqrt(time // r)
                if total >= cars:
                    return True
            return False

