class Solution:
    def minOperations(self, nums: list[int]) -> int:
        n = len(nums)
        flips = 0

        # Sweep left to right up to n - 3
        for i in range(n - 2):
            if nums[i] == 0:
                nums[i] ^= 1
                nums[i + 1] ^= 1
                nums[i + 2] ^= 1
                flips += 1

        # Check if the final two elements resolved to 1
        return flips if nums[-2] == 1 and nums[-1] == 1 else -1

