class Solution:
    def minCapability(self, nums: list[int], k: int) -> int:
        def can_rob(cap: int) -> bool:
            count = 0
            i = 0
            n = len(nums)
            while i < n:
                if nums[i] <= cap:
                    count += 1
                    i += 2  # Skip adjacent house
                else:
                    i += 1
            return count >= k

        low, high = min(nums), max(nums)
        while low < high:
            mid = low + (high - low) // 2
            if can_rob(mid):
                high = mid  # mid is feasible, try smaller
            else:
                low = mid + 1  # mid too small, must increase
        return low

