from collections import deque, defaultdict
from typing import List

class Solution:
    def findAllRecipes(
        self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]
    ) -> List[str]:
        supplies_set = set(supplies)
        graph = defaultdict(list)  # missing_ingredient -> list of dependent recipes
        in_degree = defaultdict(int)  # recipe -> count of missing ingredients

        # Build dependency graph
        for recipe, reqs in zip(recipes, ingredients):
            for ing in reqs:
                if ing not in supplies_set:
                    graph[ing].append(recipe)
                    in_degree[recipe] += 1

        # Recipes ready from the start (all ingredients in supplies)
        queue = deque([r for r in recipes if in_degree[r] == 0])
        result = []

        # Kahn's BFS
        while queue:
            curr = queue.popleft()
            result.append(curr)

            for dependent in graph[curr]:
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0:
                    queue.append(dependent)

        return result

