def jsonStringify(obj) -> str:
    # Null check
    if obj is None:
        return "null"

    # Boolean check (must precede int check in Python since bool subclasses int)
    if isinstance(obj, bool):
        return "true" if obj else "false"

    # Numbers
    if isinstance(obj, (int, float)):
        return str(obj)

    # Strings: wrap in double quotes and escape internal quotes/backslashes
    if isinstance(obj, str):
        escaped = obj.replace("\\", "\\\\").replace('"', '\\"')
        return f'"{escaped}"'

    # Arrays
    if isinstance(obj, list):
        items = [jsonStringify(item) for item in obj]
        return f"[{','.join(items)}]"

    # Objects / Dicts
    if isinstance(obj, dict):
        pairs = [f'"{k}":{jsonStringify(v)}' for k, v in obj.items()]
        return f"{{{','.join(pairs)}}}"

    return "null"

