class Solution:
    def pivotArray(self, nums: list[int], pivot: int) -> list[int]:
        n = len(nums)
        ans = [0] * n
        left, right = 0, n - 1

        # Single pass: forward for < pivot, backward for > pivot
        for i in range(n):
            if nums[i] < pivot:
                ans[left] = nums[i]
                left += 1
            if nums[n - 1 - i] > pivot:
                ans[right] = nums[n - 1 - i]
                right -= 1

        # Fill remaining middle slots with pivot
        while left <= right:
            ans[left] = pivot
            left += 1

        return ans

