class Solution:
    def lenLongestFibSubseq(self, arr: list[int]) -> int:
        n = len(arr)
        val_to_idx = {val: i for i, val in enumerate(arr)}
        # dp[j][k] stores length of sequence ending at arr[j], arr[k]
        dp = [[0] * n for _ in range(n)]
        max_len = 0

        for k in range(n):
            for j in range(k):
                diff = arr[k] - arr[j]
                # Since array is strictly increasing, diff must be strictly less than arr[j]
                if diff >= arr[j]:
                    continue

                if diff in val_to_idx:
                    i = val_to_idx[diff]
                    # Base length is 2 if dp[i][j] hasn't been set yet
                    dp[j][k] = (dp[i][j] if dp[i][j] > 0 else 2) + 1
                    if dp[j][k] > max_len:
                        max_len = dp[j][k]

        return max_len if max_len >= 3 else 0

