        min_w = current_w

        # Slide the window across the rest of the string
        for i in range(k, len(blocks)):
            if blocks[i] == 'W':
                current_w += 1
            if blocks[i - k] == 'W':
                current_w -= 1
            if current_w < min_w:
                min_w = current_w
                if min_w == 0:
                    return 0

