class Solution:
    def applyOperations(self, nums: list[int]) -> list[int]:
        n = len(nums)

        # Step 1: Apply sequential merge operations
        for i in range(n - 1):
            if nums[i] == nums[i + 1]:
                nums[i] *= 2
                nums[i + 1] = 0

        # Step 2: Shift non-zeroes to the front in-place
        write_idx = 0
        for read_idx in range(n):
            if nums[read_idx] != 0:
                nums[write_idx] = nums[read_idx]
                write_idx += 1

        # Step 3: Pad the tail with zeroes
        while write_idx < n:
            nums[write_idx] = 0
            write_idx += 1

        return nums

