class Solution:
    def countTriplets(self, arr: list[int]) -> int:
        # count[x] tracks how many times prefix XOR x has appeared
        # total_idx[x] tracks the sum of prefix indices where x appeared
        count = {0: 1}
        total_idx = {0: 0}

        prefix_xor = 0
        ans = 0

        for k, num in enumerate(arr):
            prefix_xor ^= num
            if prefix_xor in count:
                # k is the 0-based array index; prefix index is k + 1
                # For each previous prefix index i where P[i] == P[k+1]:
                # valid triplets = sum((k + 1 - 1) - i) = count * k - sum(i)
                ans += count[prefix_xor] * k - total_idx[prefix_xor]
                count[prefix_xor] += 1
                total_idx[prefix_xor] += (k + 1)
            else:
                count[prefix_xor] = 1
                total_idx[prefix_xor] = (k + 1)

        return ans

