class Solution:
    def reverseStr(self, s: str, k: int) -> str:
        chars = list(s)
        n = len(chars)

        # Step through in blocks of 2k
        for i in range(0, n, 2 * k):
            left = i
            # Clamp right pointer to end of array
            right = min(i + k - 1, n - 1)

            # Reverse the first k (or remaining) characters
            while left < right:
                chars[left], chars[right] = chars[right], chars[left]
                left += 1
                right -= 1

        return "".join(chars)

