class Solution:
    def findUnsortedSubarray(self, nums: list[int]) -> int:
        n = len(nums)
        if n <= 1:
            return 0

        start, end = -1, -2
        max_val = float('-inf')
        min_val = float('inf')

        # Single pass updating both boundaries
        for i in range(n):
            # Check from left to right for right boundary
            max_val = max(max_val, nums[i])
            if nums[i] < max_val:
                end = i

            # Check from right to left for left boundary
            j = n - 1 - i
            min_val = min(min_val, nums[j])
            if nums[j] > min_val:
                start = j

        return end - start + 1

