from collections import defaultdict

class DetectSquares:
    def __init__(self):
        # Map (x, y) -> count of occurrences
        self.counts = defaultdict(int)
        # List of unique points to iterate over in count()
        self.unique_pts = []

    def add(self, point: list[int]) -> None:
        x, y = point[0], point[1]
        if self.counts[(x, y)] == 0:
            self.unique_pts.append((x, y))
        self.counts[(x, y)] += 1

    def count(self, point: list[int]) -> int:
        px, py = point[0], point[1]
        ans = 0

        for x, y in self.unique_pts:
            # Must form a non-zero diagonal of an axis-aligned square
            dx = abs(px - x)
            dy = abs(py - y)
            if dx == dy and dx > 0:
                # The other two corners are (px, y) and (x, py)
                c1 = self.counts[(px, y)]
                c2 = self.counts[(x, py)]
                if c1 > 0 and c2 > 0:
                    ans += self.counts[(x, y)] * c1 * c2

        return ans

