# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right

class Solution:
    def replaceValueInTree(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        if not root:
            return None

        # Root never has cousins
        root.val = 0
        queue = [root]

        while queue:
            next_level_sum = 0
            # First pass: sum values of all nodes in the next level
            for node in queue:
                if node.left:
                    next_level_sum += node.left.val
                if node.right:
                    next_level_sum += node.right.val

            next_queue = []
            # Second pass: update each child with next_level_sum - sibling_sum
            for node in queue:
                sibling_sum = 0
                if node.left:
                    sibling_sum += node.left.val
                if node.right:
                    sibling_sum += node.right.val

                if node.left:
                    node.left.val = next_level_sum - sibling_sum
                    next_queue.append(node.left)
                if node.right:
                    node.right.val = next_level_sum - sibling_sum
                    next_queue.append(node.right)

            queue = next_queue

        return root

print-binary-tree.solution:
# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right

class Solution:
    def printTree(self, root: Optional[TreeNode]) -> List[List[str]]:
        # Pass 1: determine height (number of edges to deepest leaf)
        def get_height(node: Optional[TreeNode]) -> int:
            if not node:
                return -1
            return 1 + max(get_height(node.left), get_height(node.right))

        height = get_height(root)
        m = height + 1
        n = (1 << (height + 1)) - 1

        # Pre-allocate grid
        res = [["" for _ in range(n)] for _ in range(m)]

        # Pass 2: populate tree nodes into their deterministic slots
        def dfs(node: Optional[TreeNode], r: int, c: int) -> None:
            if not node:
                return
            res[r][c] = str(node.val)
            offset = 1 << (height - r - 1)
            if node.left:
                dfs(node.left, r + 1, c - offset)
            if node.right:
                dfs(node.right, r + 1, c + offset)

        dfs(root, 0, (n - 1) // 2)
        return res

