class Solution:
    def separateSquares(self, squares: list[list[int]]) -> float:
        total_area = sum(l * l for _, _, l in squares)
        target = total_area / 2.0

        low = float(min(y for _, y, _ in squares))
        high = float(max(y + l for _, y, l in squares))

        # 60 iterations give precision: (high - low) / 2^60 < 2e9 / 1e18 ~ 10^-9
        for _ in range(60):
            mid = (low + high) / 2.0
            area_below = 0.0

            for _, y, l in squares:
                if mid <= y:
                    continue
                elif mid >= y + l:
                    area_below += l * l
                else:
                    area_below += (mid - y) * l

            if area_below >= target:
                high = mid
            else:
                low = mid

        return low

