class Solution:
    def removeComments(self, source: list[str]) -> list[str]:
        in_block = False
        res: list[str] = []
        buffer: list[str] = []

        for line in source:
            i = 0
            n = len(line)

            while i < n:
                # If currently inside a block comment, look for closure
                if in_block:
                    if i + 1 < n and line[i:i+2] == "*/":
                        in_block = False
                        i += 2
                    else:
                        i += 1
                else:
                    # Not in a block comment; check for comment starts
                    if i + 1 < n and line[i:i+2] == "/*":
                        in_block = True
                        i += 2
                    elif i + 1 < n and line[i:i+2] == "//":
                        # Line comment: ignore remainder of this line
                        break
                    else:
                        buffer.append(line[i])
                        i += 1

            # Flush buffer only if we're not inside an active block comment
            if not in_block and buffer:
                res.append("".join(buffer))
                buffer = []

        return res

