class Solution:
    def asteroidCollision(self, asteroids: list[int]) -> list[int]:
        stack = []

        for ast in asteroids:
            alive = True
            # Collision only occurs if top moves right and current moves left
            while alive and ast < 0 and stack and stack[-1] > 0:
                if stack[-1] < -ast:
                    stack.pop()  # Top asteroid explodes, current continues
                elif stack[-1] == -ast:
                    stack.pop()  # Both explode
                    alive = False
                else:
                    alive = False  # Current asteroid explodes

            if alive:
                stack.append(ast)

        return stack

