class Solution:
    def canTransform(self, start: str, result: str) -> bool:
        if len(start) != len(result):
            return False

        n = len(start)
        i = j = 0

        while i < n or j < n:
            # Advance i to the next non-'X' character in start
            while i < n and start[i] == 'X':
                i += 1
            # Advance j to the next non-'X' character in result
            while j < n and result[j] == 'X':
                j += 1

            # If one finishes, both must finish
            if i == n or j == n:
                return i == j

            # Non-'X' characters must be identical
            if start[i] != result[j]:
                return False

            # 'L' can only move left, so start index must be >= result index
            if start[i] == 'L' and i < j:
                return False

            # 'R' can only move right, so start index must be <= result index
            if start[i] == 'R' and i > j:
                return False

            i += 1
            j += 1

        return True

