from collections import defaultdict
from typing import List

class Solution:
    def calcEquation(self, equations: List[List[str]], values: List[float], queries: List[List[str]]) -> List[float]:
        graph = defaultdict(dict)

        # Build the graph with bidirectional weighted edges
        for (u, v), val in zip(equations, values):
            graph[u][v] = val
            graph[v][u] = 1.0 / val

        def dfs(curr: str, target: str, acc: float, visited: set) -> float:
            if curr == target:
                return acc
            visited.add(curr)

            for neighbor, weight in graph[curr].items():
                if neighbor not in visited:
                    res = dfs(neighbor, target, acc * weight, visited)
                    if res != -1.0:
                        return res
            return -1.0

        ans = []
        for src, dst in queries:
            if src not in graph or dst not in graph:
                ans.append(-1.0)
            elif src == dst:
                ans.append(1.0)
            else:
                ans.append(dfs(src, dst, 1.0, set()))

        return ans

