class Solution:
    def constructFromPrePost(self, preorder: list[int], postorder: list[int]) -> Optional[TreeNode]:
        post_map = {val: idx for idx, val in enumerate(postorder)}

        def build(pre_start: int, pre_end: int, post_start: int, post_end: int) -> Optional[TreeNode]:
            if pre_start > pre_end:
                return None

            root = TreeNode(preorder[pre_start])
            if pre_start == pre_end:
                return root

            # Next element in preorder is root of the left subtree
            left_val = preorder[pre_start + 1]
            left_post_idx = post_map[left_val]
            left_size = left_post_idx - post_start + 1

            root.left = build(pre_start + 1, pre_start + left_size, post_start, left_post_idx)
            root.right = build(pre_start + left_size + 1, pre_end, left_post_idx + 1, post_end - 1)

            return root

        return build(0, len(preorder) - 1, 0, len(postorder) - 1)

