class Solution:
    def minAreaRect(self, points: list[list[int]]) -> int:
        # Store all points as tuples in a hash set for O(1) lookups
        point_set = set(map(tuple, points))
        min_area = float('inf')

        # Check every pair as candidate diagonal corners
        for i in range(len(points)):
            x1, y1 = points[i]
            for j in range(i + 1, len(points)):
                x2, y2 = points[j]

                # Must not share an x or y coordinate (must be diagonal)
                if x1 == x2 or y1 == y2:
                    continue

                # Check if the complementary corners exist
                if (x1, y2) in point_set and (x2, y1) in point_set:
                    area = abs(x1 - x2) * abs(y1 - y2)
                    if area < min_area:
                        min_area = area

        return min_area if min_area != float('inf') else 0

