class Solution:
    def canConstruct(self, s: str, k: int) -> bool:
        # Cannot make k non-empty strings if we don't have enough characters
        if len(s) < k:
            return False

        # Count character frequencies
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        # Palindromes can absorb at most one odd frequency character each
        odd_count = sum(1 for c in counts if c % 2 != 0)

        return odd_count <= k

