class Solution:
    def minMaxWeight(self, n: int, edges: list[list[int]], threshold: int) -> int:
        # Build reversed graph: v -> (u, w)
        rev_adj = [[] for _ in range(n)]
        max_w = 0
        for u, v, w in edges:
            rev_adj[v].append((u, w))
            if w > max_w:
                max_w = w

        def can_reach_all(limit: int) -> bool:
            visited = [False] * n
            visited[0] = True
            queue = collections.deque([0])
            count = 1

            while queue:
                curr = queue.popleft()
                for nxt, w in rev_adj[curr]:
                    if w <= limit and not visited[nxt]:
                        visited[nxt] = True
                        count += 1
                        queue.append(nxt)
            return count == n

        # If impossible even with all edges, return -1
        if not can_reach_all(max_w):
            return -1

        low, high = 1, max_w
        ans = max_w
        while low <= high:
            mid = (low + high) // 2
            if can_reach_all(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1

        return ans

