class Solution:
    def findClosestElements(self, arr: list[int], k: int, x: int) -> list[int]:
        # Search space is the set of all valid starting indices for a window of size k
        low, high = 0, len(arr) - k

        while low < high:
            mid = low + (high - low) // 2
            # If arr[mid + k] is closer to x than arr[mid], start must be to the right
            if x - arr[mid] > arr[mid + k] - x:
                low = mid + 1
            else:
                high = mid

        return arr[low : low + k]

