class Solution:
    def canBeValid(self, s: str, locked: str) -> bool:
        n = len(s)
        # An odd-length string can never be balanced
        if n % 2 != 0:
            return False

        # Forward pass: ensure no prefix has excess ')'
        open_count = 0
        for i in range(n):
            if locked[i] == '0' or s[i] == '(':
                open_count += 1
            else:
                open_count -= 1
            if open_count < 0:
                return False

        # Backward pass: ensure no suffix has excess '('
        close_count = 0
        for i in range(n - 1, -1, -1):
            if locked[i] == '0' or s[i] == ')':
                close_count += 1
            else:
                close_count -= 1
            if close_count < 0:
                return False

        return True

