import heapq
from collections import Counter

class Solution:
    def reorganizeString(self, s: str) -> str:
        counts = Counter(s)
        max_freq = max(counts.values())

        # Pigeonhole check: impossible if one char dominates
        if max_freq > (len(s) + 1) // 2:
            return ""

        # Max-heap storing (-freq, char)
        max_heap = [(-cnt, char) for char, cnt in counts.items()]
        heapq.heapify(max_heap)

        res = []
        while len(max_heap) >= 2:
            cnt1, ch1 = heapq.heappop(max_heap)
            cnt2, ch2 = heapq.heappop(max_heap)

            res.extend([ch1, ch2])

            if cnt1 + 1 < 0:
                heapq.heappush(max_heap, (cnt1 + 1, ch1))
            if cnt2 + 1 < 0:
                heapq.heappush(max_heap, (cnt2 + 1, ch2))

        # At most one leftover character
        if max_heap:
            res.append(max_heap[0][1])

        return "".join(res)

