class Solution:
    def find132pattern(self, nums: list[int]) -> bool:
        if len(nums) < 3:
            return False

        # s2 represents nums[k] (the '2' in '132')
        s2 = float('-inf')
        stack = []  # stores candidate nums[j] (the '3's)

        # Scan right-to-left
        for num in reversed(nums):
            # If current num < s2, we have found nums[i] < nums[k] < nums[j]
            if num < s2:
                return True

            # If num can be a '3', pop smaller elements to update s2
            while stack and stack[-1] < num:
                s2 = stack.pop()

            stack.append(num)

        return False

