class Solution:
    def minimizeXor(self, num1: int, num2: int) -> int:
        k = num2.bit_count()
        x = 0

        # First pass: cancel num1's highest set bits
        for i in range(31, -1, -1):
            if (num1 >> i) & 1 and k > 0:
                x |= (1 << i)
                k -= 1

        # Second pass: fill remaining bits from lowest available positions
        for i in range(32):
            if k == 0:
                break
            if not ((x >> i) & 1):
                x |= (1 << i)
                k -= 1

        return x

