import heapq

class TaskManager:
    def __init__(self, tasks: list[list[int]]):
        # Map: taskId -> (priority, userId)
        self.task_info = {}
        # Max-heap: (-priority, -taskId, userId)
        self.heap = []
        for user_id, task_id, priority in tasks:
            self.add(user_id, task_id, priority)

    def add(self, userId: int, taskId: int, priority: int) -> None:
        self.task_info[taskId] = (priority, userId)
        heapq.heappush(self.heap, (-priority, -taskId, userId))

    def edit(self, taskId: int, newPriority: int) -> None:
        _, user_id = self.task_info[taskId]
        self.task_info[taskId] = (newPriority, user_id)
        heapq.heappush(self.heap, (-newPriority, -taskId, user_id))

    def rmv(self, taskId: int) -> None:
        if taskId in self.task_info:
            del self.task_info[taskId]

    def execTop(self) -> int:
        while self.heap:
            neg_p, neg_id, user_id = heapq.heappop(self.heap)
            task_id = -neg_id
            priority = -neg_p

            # Check if this heap entry is current and valid
            if task_id in self.task_info and self.task_info[task_id] == (priority, user_id):
                del self.task_info[task_id]
                return user_id
        return -1

