class Solution:
    def isThereAPath(self, grid: list[list[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        total_len = m + n - 1

        # Odd length can never have equal 0s and 1s
        if total_len % 2 != 0:
            return False

        target = total_len // 2
        # dp[r][c] stores a bitmask of reachable counts of 1s
        dp = [[0] * n for _ in range(m)]
        dp[0][0] = 1 << grid[0][0]

        for r in range(m):
            for c in range(n):
                mask = dp[r][c]
                if not mask:
                    continue

                if r + 1 < m:
                    dp[r + 1][c] |= mask << grid[r + 1][c]
                if c + 1 < n:
                    dp[r][c + 1] |= mask << grid[r][c + 1]

        return bool(dp[m - 1][n - 1] & (1 << target))

