# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right

class Solution:
    def rob(self, root: Optional[TreeNode]) -> int:
        def dfs(node: Optional[TreeNode]) -> tuple[int, int]:
            # Returns (rob_node, skip_node)
            if not node:
                return (0, 0)

            rob_left, skip_left = dfs(node.left)
            rob_right, skip_right = dfs(node.right)

            # If we rob this node, we cannot rob either child
            rob_curr = node.val + skip_left + skip_right

            # If we skip this node, we take the best outcome from each child
            skip_curr = max(rob_left, skip_left) + max(rob_right, skip_right)

            return (rob_curr, skip_curr)

        return max(dfs(root))

