class Solution:
    def countCompleteComponents(self, n: int, edges: list[list[int]]) -> int:
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        visited = [False] * n
        complete_count = 0

        for i in range(n):
            if visited[i]:
                continue

            # Explore component via BFS
            queue = [i]
            visited[i] = True
            node_count = 0
            degree_sum = 0

            for node in queue:
                node_count += 1
                degree_sum += len(adj[node])
                for neighbour in adj[node]:
                    if not visited[neighbour]:
                        visited[neighbour] = True
                        queue.append(neighbour)

            # Handshake lemma: 2 * E_comp == degree_sum
            # For complete graph of size k: total edges = k * (k - 1) / 2 => degree_sum = k * (k - 1)
            if degree_sum == node_count * (node_count - 1):
                complete_count += 1

        return complete_count

