class Solution:
    def findTargetSumWays(self, nums: list[int], target: int) -> int:
        total = sum(nums)

        # Target is unreachable if out of range or parity doesn't match
        if abs(target) > total or (total + target) % 2 != 0:
            return 0

        subset_target = (total + target) // 2
        dp = [0] * (subset_target + 1)
        dp[0] = 1  # Base case: 1 way to make sum 0 (empty subset)

        for num in nums:
            # Traverse backwards to ensure each num is used at most once
            for s in range(subset_target, num - 1, -1):
                dp[s] += dp[s - num]

        return dp[subset_target]

