import heapq

class Solution:
    def trapRainWater(self, heightMap: list[list[int]]) -> int:
        if not heightMap or not heightMap[0]:
            return 0

        m, n = len(heightMap), len(heightMap[0])
        if m < 3 or n < 3:
            return 0

        visited = [[False] * n for _ in range(m)]
        heap = []

        # Seed the heap with all perimeter cells
        for r in range(m):
            for c in range(n):
                if r == 0 or r == m - 1 or c == 0 or c == n - 1:
                    heapq.heappush(heap, (heightMap[r][c], r, c))
                    visited[r][c] = True

        trapped_water = 0
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        # Shrink boundary inwards, lowest wall first
        while heap:
            height, r, c = heapq.heappop(heap)

            for dr, dc in directions:
                nr, nc = r + dr, c + dc

                if 0 <= nr < m and 0 <= nc < n and not visited[nr][nc]:
                    visited[nr][nc] = True
                    # Water trapped is difference between spill height and cell height
                    if heightMap[nr][nc] < height:
                        trapped_water += height - heightMap[nr][nc]

                    # The effective wall height for neighbours inside is max(height, neighbor's height)
                    heapq.heappush(heap, (max(height, heightMap[nr][nc]), nr, nc))

        return trapped_water

