        n = len(lcp)
        res = [''] * n
        c = ord('a')

        # Greedily assign the smallest available letter
        for i in range(n):
            if res[i]:
                continue
            if c > ord('z'):
                return ""
            ch = chr(c)
            for j in range(i, n):
                if lcp[i][j] > 0:
                    res[j] = ch
            c += 1

        # Validate that the candidate string produces the exact LCP matrix
        for i in range(n - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                expected = 0
                if res[i] == res[j]:
                    expected = 1 + (lcp[i + 1][j + 1] if i + 1 < n and j + 1 < n else 0)
                if lcp[i][j] != expected:
                    return ""

        return "".join(res)

range-module.solution:
from bisect import bisect_left, bisect_right

class RangeModule:
    def __init__(self):
        # Flat list of alternating starts and ends: [s0, e0, s1, e1, ...]
        self.bounds = []

    def addRange(self, left: int, right: int) -> None:
        i = bisect_left(self.bounds, left)
        j = bisect_right(self.bounds, right)

        # Collect new boundary points to inject
        sub = []
        if i % 2 == 0:
            sub.append(left)
        if j % 2 == 0:
            sub.append(right)

        self.bounds[i:j] = sub

    def queryRange(self, left: int, right: int) -> bool:
        i = bisect_right(self.bounds, left)
        j = bisect_left(self.bounds, right)
        # Both endpoints must fall inside the exact same active interval
        return i == j and i % 2 == 1

    def removeRange(self, left: int, right: int) -> None:
        i = bisect_left(self.bounds, left)
        j = bisect_right(self.bounds, right)

        # Collect boundary points created by splitting existing intervals
        sub = []
        if i % 2 == 1:
            sub.append(left)
        if j % 2 == 1:
            sub.append(right)

        self.bounds[i:j] = sub

