from collections import defaultdict, deque

def alienOrder(words: list[str]) -> str:
    # 1. Collect all unique characters
    adj = {c: set() for word in words for c in word}
    in_degree = {c: 0 for c in adj}

    # 2. Build graph from adjacent word differences
    for i in range(len(words) - 1):
        w1, w2 = words[i], words[i + 1]
        min_len = min(len(w1), len(w2))

        # Prefix edge case: e.g., ("abc", "ab") is invalid
        if len(w1) > len(w2) and w1[:min_len] == w2[:min_len]:
            return ""

        for j in range(min_len):
            if w1[j] != w2[j]:
                c1, c2 = w1[j], w2[j]
                if c2 not in adj[c1]:
                    adj[c1].add(c2)
                    in_degree[c2] += 1
                break

    # 3. Kahn's Algorithm (BFS)
    queue = deque([c for c, deg in in_degree.items() if deg == 0])
    res = []

    while queue:
        curr = queue.popleft()
        res.append(curr)
        for nxt in adj[curr]:
            in_degree[nxt] -= 1
            if in_degree[nxt] == 0:
                queue.append(nxt)

    # 4. Check for cycle
    return "".join(res) if len(res) == len(in_degree) else ""

