import heapq
from typing import List

class Solution:
    def minimumWeight(self, n: int, edges: List[List[int]], src1: int, src2: int, dest: int) -> int:
        # Build forward and reversed graphs
        graph = [[] for _ in range(n)]
        rev_graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            rev_graph[v].append((u, w))

        def dijkstra(start: int, adj: List[List[tuple[int, int]]]) -> List[float]:
            dist = [float('inf')] * n
            dist[start] = 0
            pq = [(0, start)]
            while pq:
                d, u = heapq.heappop(pq)
                if d > dist[u]:
                    continue
                for v, w in adj[u]:
                    if dist[u] + w < dist[v]:
                        dist[v] = dist[u] + w
                        heapq.heappush(pq, (dist[v], v))
            return dist

        # Run three Dijkstra searches
        d1 = dijkstra(src1, graph)
        d2 = dijkstra(src2, graph)
        d_dest = dijkstra(dest, rev_graph)

        # Find the optimal convergence node x
        ans = float('inf')
        for x in range(n):
            if d1[x] < float('inf') and d2[x] < float('inf') and d_dest[x] < float('inf'):
                ans = min(ans, d1[x] + d2[x] + d_dest[x])

        return ans if ans < float('inf') else -1

