class Solution:
    def minimumCost(self, n: int, edges: list[list[int]], query: list[list[int]]) -> list[int]:
        parent = list(range(n))
        rank = [0] * n
        # Initialize component bitwise AND mask to all 1s
        comp_cost = [(1 << 30) - 1] * n

        def find(i: int) -> int:
            if parent[i] == i:
                return i
            parent[i] = find(parent[i])
            return parent[i]

        def union(u: int, v: int, w: int) -> None:
            root_u = find(u)
            root_v = find(v)

            if root_u == root_v:
                comp_cost[root_u] &= w
                return

            # Union by rank
            if rank[root_u] < rank[root_v]:
                root_u, root_v = root_v, root_u

            parent[root_v] = root_u
            comp_cost[root_u] = comp_cost[root_u] & comp_cost[root_v] & w
            if rank[root_u] == rank[root_v]:
                rank[root_u] += 1

        for u, v, w in edges:
            union(u, v, w)

        res = []
        for s, t in query:
            root_s = find(s)
            root_t = find(t)
            if root_s != root_t:
                res.append(-1)
            else:
                res.append(comp_cost[root_s])

        return res

