class Solution:
    def numIslands2(self, m: int, n: int, positions: list[list[int]]) -> list[int]:
        # Flat index: r * n + c
        parent = [-1] * (m * n)
        rank = [0] * (m * n)

        def find(i: int) -> int:
            if parent[i] != i:
                parent[i] = find(parent[i])  # Path compression
            return parent[i]

        def union(i: int, j: int) -> bool:
            root_i, root_j = find(i), find(j)
            if root_i == root_j:
                return False
            # Union by rank
            if rank[root_i] < rank[root_j]:
                parent[root_i] = root_j
            elif rank[root_i] > rank[root_j]:
                parent[root_j] = root_i
            else:
                parent[root_j] = root_i
                rank[root_i] += 1
            return True

        ans = []
        count = 0

        for r, c in positions:
            idx = r * n + c
            # Already turned into land, skip re-adding
            if parent[idx] != -1:
                ans.append(count)
                continue

            parent[idx] = idx
            count += 1

            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    n_idx = nr * n + nc
                    if parent[n_idx] != -1 and union(idx, n_idx):
                        count -= 1

            ans.append(count)

        return ans

