class Solution:
    def findPermutation(self, nums: list[int]) -> list[int]:
        n = len(nums)
        memo = {}

        def get_min_score(mask: int, last: int) -> int:
            # Base case: all nodes visited, close the cycle back to 0
            if mask == (1 << n) - 1:
                return abs(last - nums[0])

            state = (mask, last)
            if state in memo:
                return memo[state]

            min_cost = float('inf')
            for nxt in range(1, n):
                if not (mask & (1 << nxt)):
                    cost = abs(last - nums[nxt]) + get_min_score(mask | (1 << nxt), nxt)
                    if cost < min_cost:
                        min_cost = cost

            memo[state] = min_cost
            return min_cost

        # Reconstruct path lexicographically
        ans = [0]
        mask = 1
        last = 0

        for _ in range(n - 1):
            for nxt in range(1, n):
                if not (mask & (1 << nxt)):
                    cost = abs(last - nums[nxt]) + get_min_score(mask | (1 << nxt), nxt)
                    if cost == get_min_score(mask, last):
                        ans.append(nxt)
                        mask |= (1 << nxt)
                        last = nxt
                        break

        return ans

