class Solution:
    def minStartingIndex(self, s: str, pattern: str) -> int:
        n, m = len(s), len(pattern)

        def get_z(text: str) -> list[int]:
            z = [0] * len(text)
            l, r = 0, 0
            for i in range(1, len(text)):
                if i <= r:
                    z[i] = min(r - i + 1, z[i - l])
                while i + z[i] < len(text) and text[z[i]] == text[i + z[i]]:
                    z[i] += 1
                if i + z[i] - 1 > r:
                    l, r = i, i + z[i] - 1
            return z

        # Forward Z-array: LCP of pattern and s[i..]
        z_fwd = get_z(pattern + "$" + s)
        # Backward Z-array: LCS of pattern and s[..i+m-1]
        z_bwd = get_z(pattern[::-1] + "$" + s[::-1])

        for i in range(n - m + 1):
            lcp = min(m, z_fwd[m + 1 + i])
            lcs = min(m, z_bwd[m + 1 + (n - m - i)])
            if lcp + lcs >= m - 1:
                return i

        return -1

