from collections import deque

class Solution:
    def shortestDistance(self, grid: list[list[int]]) -> int:
        R, C = len(grid), len(grid[0])
        total_dist = [[0] * C for _ in range(R)]
        empty_val = 0
        min_dist = 0

        for r in range(R):
            for c in range(C):
                if grid[r][c] == 1:
                    min_dist = float('inf')
                    q = deque([(r, c, 0)])

                    while q:
                        curr_r, curr_c, d = q.popleft()
                        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == empty_val:
                                grid[nr][nc] -= 1
                                total_dist[nr][nc] += d + 1
                                min_dist = min(min_dist, total_dist[nr][nc])
                                q.append((nr, nc, d + 1))

                    # If this building couldn't reach any candidate cell, impossible
                    if min_dist == float('inf'):
                        return -1

                    empty_val -= 1

        return min_dist if min_dist != float('inf') else -1

