import heapq

class Solution:
    def swimInWater(self, grid: list[list[int]]) -> int:
        n = len(grid)
        # Min-heap stores tuples of (max_elevation_so_far, r, c)
        pq = [(grid[0][0], 0, 0)]
        visited = [[False] * n for _ in range(n)]
        visited[0][0] = True

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while pq:
            time, r, c = heapq.heappop(pq)

            if r == n - 1 and c == n - 1:
                return time

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and not visited[nr][nc]:
                    visited[nr][nc] = True
                    # The bottleneck time is max of current path and new cell
                    heapq.heappush(pq, (max(time, grid[nr][nc]), nr, nc))

        return -1

