class Solution:
    def findSecretWord(self, words: list[str], master: 'Master') -> None:
        def get_matches(w1: str, w2: str) -> int:
            return sum(c1 == c2 for c1, c2 in zip(w1, w2))

        candidates = list(words)

        for _ in range(30):
            # Minimax: pick candidate that minimizes the largest bucket
            best_word = None
            min_max_bucket = float('inf')

            for w1 in candidates:
                buckets = [0] * 7
                for w2 in candidates:
                    if w1 != w2:
                        buckets[get_matches(w1, w2)] += 1
                max_bucket = max(buckets)
                if max_bucket < min_max_bucket:
                    min_max_bucket = max_bucket
                    best_word = w1

            matches = master.guess(best_word)
            if matches == 6:
                return

            # Retain only words consistent with this observation
            candidates = [w for w in candidates if get_matches(best_word, w) == matches]

