#    def length(self) -> int:

class Solution:
    def findInMountainArray(self, target: int, mountain_arr: 'MountainArray') -> int:
        n = mountain_arr.length()
        cache = {}

        def get(i: int) -> int:
            if i not in cache:
                cache[i] = mountain_arr.get(i)
            return cache[i]

        # 1. Find the peak index
        low, high = 0, n - 1
        while low < high:
            mid = (low + high) // 2
            if get(mid) < get(mid + 1):
                low = mid + 1
            else:
                high = mid
        peak = low

        # 2. Search ascending left slope [0, peak]
        low, high = 0, peak
        while low <= high:
            mid = (low + high) // 2
            val = get(mid)
            if val == target:
                return mid
            elif val < target:
                low = mid + 1
            else:
                high = mid - 1

        # 3. Search descending right slope [peak + 1, n - 1]
        low, high = peak + 1, n - 1
        while low <= high:
            mid = (low + high) // 2
            val = get(mid)
            if val == target:
                return mid
            elif val > target:
                low = mid + 1
            else:
                high = mid - 1

        return -1

