from collections import defaultdict
from typing import List, Dict, Tuple

class Excel:
    def __init__(self, height: int, width: str):
        self.h = height
        self.w = ord(width) - ord('A') + 1
        self.val = [[0] * self.w for _ in range(self.h)]
        self.formula: List[List[Dict[Tuple[int, int], int] | None]] = [[None] * self.w for _ in range(self.h)]

    def _to_idx(self, row: int, col: str) -> Tuple[int, int]:
        return row - 1, ord(col) - ord('A')

    def _parse_cell(self, s: str) -> Tuple[int, int]:
        return int(s[1:]) - 1, ord(s[0]) - ord('A')

    def set(self, row: int, column: str, val: int) -> None:
        r, c = self._to_idx(row, column)
        self.formula[r][c] = None
        self.val[r][c] = val

    def get(self, row: int, column: str) -> int:
        r, c = self._to_idx(row, column)
        if self.formula[r][c] is None:
            return self.val[r][c]
        total = 0
        for (dr, dc), count in self.formula[r][c].items():
            # Convert 0-indexed back to 1-indexed / char for recursive call
            total += count * self.get(dr + 1, chr(ord('A') + dc))
        return total

    def sum(self, row: int, column: str, numbers: List[str]) -> int:
        r, c = self._to_idx(row, column)
        deps: Dict[Tuple[int, int], int] = defaultdict(int)
        for token in numbers:
            if ':' in token:
                top_left, bottom_right = token.split(':')
                r1, c1 = self._parse_cell(top_left)
                r2, c2 = self._parse_cell(bottom_right)
                for rr in range(r1, r2 + 1):
                    for cc in range(c1, c2 + 1):
                        deps[(rr, cc)] += 1
            else:
                deps[self._parse_cell(token)] += 1
        self.formula[r][c] = deps
        return self.get(row, column)

