class Solution:
    def shortestSuperstring(self, words: list[str]) -> str:
        n = len(words)
        # Step 1: Precompute overlaps
        overlap = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                w1, w2 = words[i], words[j]
                max_k = min(len(w1), len(w2))
                for k in range(max_k, 0, -1):
                    if w1.endswith(w2[:k]):
                        overlap[i][j] = k
                        break

        # Step 2: Bitmask DP - dp[mask][i] = max overlap ending at word i
        dp = [[0] * n for _ in range(1 << n)]
        parent = [[-1] * n for _ in range(1 << n)]

        for mask in range(1, 1 << n):
            for i in range(n):
                if not (mask & (1 << i)):
                    continue
                for j in range(n):
                    if mask & (1 << j):
                        continue
                    next_mask = mask | (1 << j)
                    val = dp[mask][i] + overlap[i][j]
                    if val >= dp[next_mask][j]:
                        dp[next_mask][j] = val
                        parent[next_mask][j] = i

        # Step 3: Find best ending word in full mask
        full_mask = (1 << n) - 1
        best_last = 0
        max_overlap = -1
        for i in range(n):
            if dp[full_mask][i] > max_overlap:
                max_overlap = dp[full_mask][i]
                best_last = i

        # Step 4: Reconstruct path
        path = []
        curr = best_last
        curr_mask = full_mask
        while curr != -1:
            path.append(curr)
            p = parent[curr_mask][curr]
            curr_mask ^= (1 << curr)
            curr = p
        path.reverse()

        # Step 5: Build final string
        res = [words[path[0]]]
        for idx in range(1, n):
            prev_w, next_w = path[idx - 1], path[idx]
            k = overlap[prev_w][next_w]
            res.append(words[next_w][k:])

        return "".join(res)

