class Solution:
    def numberOfPowerfulInt(self, start: int, finish: int, limit: int, s: str) -> int:
        def count(n: int) -> int:
            num_str = str(n)
            if len(num_str) < len(s):
                return 0

            L = len(num_str) - len(s)
            ans = 0

            # Match prefix of length L
            for i in range(L):
                d = int(num_str[i])
                if d > limit:
                    # Can place any digit 0..limit here, then all remaining prefix digits free
                    ans += (limit + 1) ** (L - i)
                    return ans
                # Place 0..(d - 1), remaining prefix digits are free
                ans += d * ((limit + 1) ** (L - 1 - i))

            # If we matched the entire prefix tightly, check if suffix is valid
            if num_str[L:] >= s:
                ans += 1
            return ans

        return count(finish) - count(start - 1)

