        for i, val in enumerate(nums1):
            p = pos2[val]
            # Query count of seen elements with pos2 index < p
            left = bit.query(p)
            # Elements after p in nums2 minus elements seen in nums1 placed after p
            right = (n - 1 - p) - (i - left)
            ans += left * right
            # Insert p into Fenwick tree (1-indexed)
            bit.update(p + 1, 1)

        return ans

minimum-number-of-days-to-eat-n-oranges.solution:
class Solution:
    def minDays(self, n: int) -> int:
        memo = {}

        def solve(rem: int) -> int:
            # Base cases: 0 oranges take 0 days, 1 takes 1 day
            if rem <= 1:
                return rem
            if rem in memo:
                return memo[rem]

            # Option A: subtract rem % 2 times, then divide by 2 (1 day)
            # Option B: subtract rem % 3 times, then divide by 3 (1 day)
            res = 1 + min(rem % 2 + solve(rem // 2), rem % 3 + solve(rem // 3))
            memo[rem] = res
            return res

        return solve(n)

word-search-ii.solution:
class TrieNode:
    def __init__(self):
        self.children = {}
        self.word = None

class Solution:
    def findWords(self, board: list[list[str]], words: list[str]) -> list[str]:
        # 1. Build the Trie
        root = TrieNode()
        for w in words:
            curr = root
            for ch in w:
                curr = curr.children.setdefault(ch, TrieNode())
            curr.word = w

        rows, cols = len(board), len(board[0])
        result = []

        def dfs(r: int, c: int, parent: TrieNode):
            ch = board[r][c]
            curr_node = parent.children[ch]

            # Check if we formed a valid word
            if curr_node.word:
                result.append(curr_node.word)
                curr_node.word = None  # Avoid duplicates

            # Mark visited
            board[r][c] = '#'

            # Explore 4 neighbours
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and board[nr][nc] in curr_node.children:
                    dfs(nr, nc, curr_node)

            # Backtrack
            board[r][c] = ch

            # Trie pruning: remove leaf node to speed up subsequent searches
            if not curr_node.children:
                del parent.children[ch]

        # 2. Search board
        for r in range(rows):
            for c in range(cols):
                if board[r][c] in root.children:
                    dfs(r, c, root)

        return result

stickers-to-spell-word.solution:
class Solution:
    def minStickers(self, stickers: list[str], target: str) -> int:
        m = len(target)
        # Pre-filter stickers: only keep letters present in target
        target_set = set(target)
        filtered = []
        for s in stickers:
            cnt = {}
            for ch in s:
                if ch in target_set:
                    cnt[ch] = cnt.get(ch, 0) + 1
            if cnt:
                filtered.append(cnt)

        memo = {}

        def dp(mask: int) -> int:
            if mask == (1 << m) - 1:
                return 0
            if mask in memo:
                return memo[mask]

            # Symmetry breaker: find the first unset bit
            first = 0
            while (mask >> first) & 1:
                first += 1

            target_char = target[first]
            res = float('inf')

            for cnt in filtered:
                # Only consider stickers that can cover this specific needed character
                if target_char not in cnt:
                    continue

                avail = dict(cnt)
                next_mask = mask
                for i in range(m):
                    if not ((next_mask >> i) & 1) and target[i] in avail and avail[target[i]] > 0:
                        avail[target[i]] -= 1
                        next_mask |= (1 << i)

                res = min(res, 1 + dp(next_mask))

            memo[mask] = res
            return res

        ans = dp(0)
        return ans if ans != float('inf') else -1

word-break-ii.solution:
class Solution:
    def wordBreak(self, s: str, wordDict: list[str]) -> list[str]:
        word_set = set(wordDict)
        max_len = max(len(w) for w in wordDict) if wordDict else 0
        memo = {}

        def dfs(start: int) -> list[str]:
            if start == len(s):
                return [""]
            if start in memo:
                return memo[start]

            valid_sentences = []
            # Prune prefix search to max possible word length
            for end in range(start + 1, min(len(s) + 1, start + max_len + 1)):
                word = s[start:end]
                if word in word_set:
                    tails = dfs(end)
                    for tail in tails:
                        sentence = word + (" " + tail if tail else "")
                        valid_sentences.append(sentence)

            memo[start] = valid_sentences
            return valid_sentences

        return dfs(0)

concatenated-words.solution:
class Solution:
    def findAllConcatenatedWordsInADict(self, words: list[str]) -> list[str]:
        # Sort by length: shorter building blocks are processed first
        words.sort(key=len)
        seen = set()
        res = []

        def can_form(word: str) -> bool:
            if not seen:
                return False
            n = len(word)
            dp = [False] * (n + 1)
            dp[0] = True
            for i in range(1, n + 1):
                for j in range(i):
                    if dp[j] and word[j:i] in seen:
                        dp[i] = True
                        break
            return dp[n]

        for word in words:
            if can_form(word):
                res.append(word)
            seen.add(word)

        return res
